// Tata bahasa + terjemahan Indonesia (otomatis via Google Translate).
export default [{"pattern":"A その上 B","meaning":"Used to express 'in addition to', 'besides', or 'furthermore' when adding information or making a suggestion.","meaningId":"Digunakan untuk menyatakan 'selain', 'selain', atau 'selanjutnya' ketika menambahkan informasi atau memberikan saran.","formation":"A [sentence/clause] + その上 + B [sentence/clause]","formationId":"A [kalimat/klausa] + その上 + B [kalimat/klausa]","examples":[{"jp":"彼は頭が良い。その上、スポーツも得意だ。","romaji":"Kare wa atama ga ii. Sono ue, supootsu mo tokui da.","en":"He is smart. In addition, he is also good at sports.","id":"Dia pintar. Selain itu, ia juga pandai dalam bidang olahraga."},{"jp":"このカフェは雰囲気がいい。その上、料理も美味しい。","romaji":"Kono kafe wa fun'iki ga ii. Sono ue, ryouri mo oishii.","en":"This cafe has a nice atmosphere. Besides, the food is delicious.","id":"Kafe ini memiliki suasana yang menyenangkan. Selain itu, makanannya enak."},{"jp":"このアパートは駅に近い。その上、家賃も安い。","romaji":"Kono apaato wa eki ni chikai. Sono ue, yachin mo yasui.","en":"This apartment is close to the station. Furthermore, the rent is also cheap.","id":"Apartemen ini dekat dengan stasiun. Selain itu, harga sewanya juga murah."},{"jp":"彼女は仕事ができる。その上、誰とでも仲良くなれる。","romaji":"Kanojo wa shigoto ga dekiru. Sono ue, dare to demo nakayoku nareru.","en":"She is competent at work. In addition, she can get along with anyone.","id":"Dia kompeten dalam bekerja. Selain itu, dia bisa bergaul dengan siapa saja."}]},{"pattern":"～うちに (〜uchi ni)","meaning":"Express 'while', 'before', or 'during' a certain condition or situation.","meaningId":"Menyatakan 'sementara', 'sebelum', atau 'selama' suatu kondisi atau situasi tertentu.","formation":"Verb-てform + いる + うちに, い-Adjective + い + うちに, な-Adjective + な + うちに","formationId":"Kata Kerja-てbentuk + いる + うちに, い-Kata Sifat + い + うちに, な-Kata Sifat + な + うちに","examples":[{"jp":"若いうちに、いろいろな経験をしておくことが大切です。","romaji":"Wakai uchi ni, iroiro na keiken wo shite oku koto ga taisetsu desu.","en":"It is important to have various experiences while you are young.","id":"Penting untuk memiliki berbagai pengalaman saat Anda masih muda."},{"jp":"雨が降っていないうちに、買い物に行こう。","romaji":"Ame ga futte inai uchi ni, kaimono ni ikou.","en":"Let's go shopping before it starts raining.","id":"Ayo berbelanja sebelum hujan mulai turun."},{"jp":"料理が熱いうちに食べましょう。","romaji":"Ryouri ga atsui uchi ni tabemashou.","en":"Let's eat while the food is still hot.","id":"Ayo makan selagi makanan masih panas."},{"jp":"休みのうちに、旅行の計画を立てたいです。","romaji":"Yasumi no uchi ni, ryokou no keikaku wo tatetai desu.","en":"I want to plan a trip during the holidays.","id":"Saya ingin merencanakan perjalanan selama liburan."}]},{"pattern":"～うとした (〜uto shita)","meaning":"Express an action someone tried to do but couldn't; 'tried to', 'attempted to'.","meaningId":"Ekspresikan tindakan yang coba dilakukan seseorang tetapi tidak bisa; 'mencoba', 'mencoba'.","formation":"Verb-う stem + とした","formationId":"Kata kerja-う batang + とした","examples":[{"jp":"電話に出ようとしたが、相手は切ってしまった。","romaji":"Denwa ni deyou to shita ga, aite wa kitte shimatta.","en":"I tried to answer the phone, but the other person hung up.","id":"Saya mencoba menjawab telepon, tetapi orang lain menutup telepon."},{"jp":"彼は大声で話そうとしたが、言葉が出なかった。","romaji":"Kare wa oogoe de hanasou to shita ga, kotoba ga denakatta.","en":"He tried to speak loudly, but no words came out.","id":"Dia mencoba berbicara dengan keras, tetapi tidak ada kata yang keluar."},{"jp":"ケーキを作ろうとしたが、材料が足りなかった。","romaji":"Keeki wo tsukurou to shita ga, zairyou ga tarinakatta.","en":"I tried to make a cake, but I didn't have enough ingredients.","id":"Saya mencoba membuat kue, tetapi bahannya tidak cukup."},{"jp":"彼女は泳ごうとしたが、怖くて水に入れなかった。","romaji":"Kanojo wa oyogou to shita ga, kowakute mizu ni irenakatta.","en":"She tried to swim, but she was scared and couldn't get in the water.","id":"Dia mencoba berenang, tapi dia takut dan tidak bisa masuk ke dalam air."}]},{"pattern":"～おかげで (〜okagede)","meaning":"Expresses gratitude or shows a positive result due to a certain factor; 'thanks to', 'because of'.","meaningId":"Mengungkapkan rasa syukur atau menunjukkan hasil positif karena suatu faktor tertentu; 'berkat', 'karena'.","formation":"Verb-casual + おかげで, い-Adjective + おかげで, な-Adjective + だおかげで, Noun + のおかげで","formationId":"Kata Kerja-kasual + おかげで, い-Kata Sifat + おかげで, な-Kata Sifat + だおかげで, Kata Benda + のおかげで","examples":[{"jp":"お母さんのおかげで、私は元気になりました。","romaji":"Okaasan no okagede, watashi wa genki ni narimashita.","en":"Thanks to my mother, I became healthy.","id":"Berkat ibu saya, saya menjadi sehat."},{"jp":"先生の助けのおかげで、試験に合格しました。","romaji":"Sensei no tasuke no okagede, shiken ni goukaku shimashita.","en":"Thanks to the teacher's help, I passed the exam.","id":"Berkat bantuan guru, saya lulus ujian."},{"jp":"日本語の勉強のおかげで、この映画が理解できました。","romaji":"Nihongo no benkyou no okagede, kono eiga ga rikai dekimashita.","en":"Thanks to studying Japanese, I was able to understand this movie.","id":"Berkat belajar bahasa Jepang, saya bisa memahami film ini."},{"jp":"晴れた天気のおかげで、ピクニックが楽しかったです。","romaji":"Hareta tenki no okagede, pikunikku ga tanoshikatta desu.","en":"Thanks to the sunny weather, the picnic was enjoyable.","id":"Berkat cuaca cerah, piknik menjadi menyenangkan."}]},{"pattern":"～かけ (〜kake)","meaning":"Expresses the meaning of being in the middle of doing something or of something being partway done.","meaningId":"Mengungkapkan arti berada di tengah-tengah melakukan sesuatu atau sesuatu sedang dilakukan.","formation":"Verb-ますstem + かけ","formationId":"Kata kerja-ますbatang + かけ","examples":[{"jp":"彼は食事を食べかけです。","romaji":"Kare wa shokuji wo tabekake desu.","en":"He is in the middle of eating his meal.","id":"Dia sedang memakan makanannya."},{"jp":"この本は読みかけで、まだ終わっていません。","romaji":"Kono hon wa yomikake de, mada owatteimasen.","en":"This book is partway read, and it is not yet finished.","id":"Buku ini sedang dibaca sebagian, dan belum selesai."},{"jp":"この部屋は掃除しかけで、まだ片づいていません。","romaji":"Kono heya wa soujishikake de, mada kataduiteimasen.","en":"This room is partway cleaned, and it's not yet tidied up.","id":"Ruangan ini sudah dibersihkan sebagian, dan belum dirapikan."},{"jp":"プロジェクトは進行しかけで、来週には完了する予定です。","romaji":"Purojekuto wa shinkoushikake de, raishuu ni wa kanryou suru yotei desu.","en":"The project is in progress and is scheduled to be completed next week.","id":"Proyek tersebut sedang dalam pengerjaan dan dijadwalkan selesai minggu depan."}]},{"pattern":"～かなあ (〜kanaa)","meaning":"Expressing uncertainty or a mild wish; 'I wonder', 'maybe'.","meaningId":"Mengekspresikan ketidakpastian atau keinginan yang ringan; 'Aku penasaran', 'mungkin'.","formation":"Verb-casual + かなあ, い-Adjective + かなあ, な-Adjective + だかなあ, Noun + だかなあ","formationId":"Kata Kerja-kasual + かなあ, い-Kata Sifat + かなあ, な-Kata Sifat + だかなあ, Kata Benda + だかなあ","examples":[{"jp":"明日晴れるかなあ。","romaji":"Ashita hareru kanaa.","en":"I wonder if it will be sunny tomorrow.","id":"Aku ingin tahu apakah besok akan cerah."},{"jp":"このスープ、辛いかなあ。","romaji":"Kono suupu, karai kanaa.","en":"I wonder if this soup is spicy.","id":"Aku ingin tahu apakah sup ini pedas."},{"jp":"彼は静かだかなあ。","romaji":"Kare wa shizuka da kanaa.","en":"I wonder if he is quiet.","id":"Aku ingin tahu apakah dia diam."},{"jp":"彼女は医者だかなあ。","romaji":"Kanojo wa isha da kanaa.","en":"I wonder if she is a doctor.","id":"Aku ingin tahu apakah dia seorang dokter."}]},{"pattern":"～ないで (〜naide)","meaning":"Express 'without doing ~' or 'without ~ing'.","meaningId":"Ekspresikan 'tanpa melakukan ~' atau 'tanpa ~ing'.","formation":"Verb-ない-form + で","formationId":"Kata kerja-ない-bentuk + で","examples":[{"jp":"会わないでその電話をかけました。","romaji":"Awanai de sono denwa wo kakemashita.","en":"I made the phone call without meeting them.","id":"Saya menelepon tanpa menemui mereka."},{"jp":"雨が降るのを待たないで、家を出ました。","romaji":"Ame ga furu no wo matanai de, ie wo demashita.","en":"I left the house without waiting for it to rain.","id":"Saya meninggalkan rumah tanpa menunggu hujan turun."},{"jp":"誰にも聞かないで、その秘密を知りました。","romaji":"Dare ni mo kikanai de, sono himitsu wo shirimashita.","en":"I found out the secret without asking anyone.","id":"Saya menemukan rahasianya tanpa bertanya kepada siapa pun."},{"jp":"遅れることを知らないで、駅に向かいました。","romaji":"Okureru koto wo shiranai de, eki ni mukaimashita.","en":"I headed to the station without knowing I was late.","id":"Aku menuju ke stasiun tanpa sadar aku terlambat."}]},{"pattern":"～から～にかけて (〜kara 〜ni kakete)","meaning":"Expresses a range of something, such as time or space; 'from...to', 'between'.","meaningId":"Mengekspresikan rentang sesuatu, seperti waktu atau ruang; 'dari...ke', 'antara'.","formation":"Noun (time, place, or measure) + から + Noun (time, place or measure) + にかけて","formationId":"Kata Benda (waktu, tempat, atau ukuran) + から + Kata Benda (waktu, tempat, atau ukuran) + にかけて","examples":[{"jp":"午前８時から午後５時にかけて働いています。","romaji":"Gozen hachiji kara gogo goji ni kakete hataraiteru.","en":"I work from 8 am to 5 pm.","id":"Saya bekerja dari jam 8 pagi sampai jam 5 sore."},{"jp":"この地域は、北から南にかけて狭いです。","romaji":"Kono chiiki wa, kita kara minami ni kakete semai desu.","en":"This area is narrow from north to south.","id":"Daerah ini sempit dari utara ke selatan."},{"jp":"１０歳から２０歳にかけて成長が早いです。","romaji":"Jussai kara nijussai ni kakete seichou ga hayai desu.","en":"Growth is rapid from 10 to 20 years of age.","id":"Pertumbuhannya cepat pada usia 10 hingga 20 tahun."},{"jp":"今年の夏は、６月から８月にかけて雨が多かった。","romaji":"Kotoshi no natsu wa, roku gatsu kara hachi gatsu ni kakete ame ga ookatta.","en":"This summer, there was a lot of rain from June to August.","id":"Musim panas ini, terjadi banyak hujan dari bulan Juni hingga Agustus."}]},{"pattern":"～かわりに (〜kawari ni)","meaning":"In place of; instead of; as a substitute for.","meaningId":"Sebagai pengganti; alih-alih; sebagai pengganti.","formation":"Verb-casual + かわりに, い-Adjective + かわりに, な-Adjective + だかわりに, Noun + だかわりに","formationId":"Kata Kerja-kasual + かわりに, い-Kata Sifat + かわりに, な-Kata Sifat + だかわりに, Kata Benda + だかわりに","examples":[{"jp":"映画を見るかわりに、本を読んだ。","romaji":"Eiga wo miru kawari ni, hon wo yonda.","en":"Instead of watching a movie, I read a book.","id":"Daripada menonton film, saya membaca buku."},{"jp":"お酒を飲むかわりに、水を飲んでください。","romaji":"Osake wo nomu kawari ni, mizu wo nonde kudasai.","en":"Please drink water instead of alcohol.","id":"Silakan minum air putih sebagai pengganti alkohol."},{"jp":"犬のかわりに、猫を飼いたいです。","romaji":"Inu no kawari ni, neko wo kaitai desu.","en":"I want to keep a cat instead of a dog.","id":"Saya ingin memelihara kucing, bukan anjing."},{"jp":"電車を使わないかわりに、自転車で行くことにしました。","romaji":"Densha wo tsukawanai kawari ni, jitensha de iku koto ni shimashita.","en":"I decided to go by bicycle instead of using the train.","id":"Saya memutuskan untuk pergi menggunakan sepeda daripada menggunakan kereta."}]},{"pattern":"～きり (〜kiri)","meaning":"Expresses the idea of 'only', 'since', or 'after'.","meaningId":"Mengungkapkan gagasan 'hanya', 'sejak', atau 'setelah'.","formation":"Verb-past + きり, Verb-てform + きり (less common), Noun + きり","formationId":"Kata kerja-masa lalu + きり, Bentuk kata kerja-て + きり (kurang umum), Kata Benda + きり","examples":[{"jp":"彼は出かけたきり帰ってきません。","romaji":"Kare wa dekaketa kiri kaette kimasen.","en":"He went out and hasn't come back since.","id":"Dia keluar dan belum kembali sejak itu."},{"jp":"昨日コーヒーを飲んだきり、何も飲まなかった。","romaji":"Kinou koohii wo nonda kiri, nani mo nomanakatta.","en":"I haven't had anything to drink since the coffee I had yesterday.","id":"Saya belum minum apa pun sejak kopi yang saya minum kemarin."},{"jp":"卒業したきり、彼女に会っていません。","romaji":"Sotsugyou shita kiri, kanojo ni atte imasen.","en":"I haven't seen her since we graduated.","id":"Aku belum melihatnya lagi sejak kami lulus."},{"jp":"その映画を見たきり、もう一度見たいと思っています。","romaji":"Sono eiga wo mita kiri, mou ichido mitai to omotteimasu.","en":"I've wanted to watch that movie again ever since I saw it.","id":"Saya ingin menonton film itu lagi sejak saya melihatnya."}]},{"pattern":"～くせに (〜kuse ni)","meaning":"Used to express criticism or disapproval; 'even though', 'despite', 'in spite of'.","meaningId":"Digunakan untuk menyatakan kritik atau ketidaksetujuan; 'walaupun', 'meskipun', 'meskipun'.","formation":"Verb-casual + くせに, い-Adjective + くせに, な-Adjective + な/のくせに, Noun + のくせに","formationId":"Kata Kerja-kasual + くせに, い-Kata Sifat + くせに, な-Kata Sifat + な/のくせに, Kata Benda + のくせに","examples":[{"jp":"彼はお金持ちのくせに、ケチです。","romaji":"Kare wa okanemochi no kuse ni, kechi desu.","en":"Even though he's rich, he's stingy.","id":"Meskipun dia kaya, dia pelit."},{"jp":"この部屋が汚いくせに、文句を言うな。","romaji":"Kono heya ga kitanai kuse ni, monku wo iu na.","en":"Don't complain even though this room is dirty. (criticizing)","id":"Jangan mengeluh meskipun ruangan ini kotor. (mengkritik)"},{"jp":"彼は暇なくせに、手伝ってくれません。","romaji":"Kare wa hima na kuse ni, tetsudatte kuremasen.","en":"Even though he's free, he won't help me.","id":"Meskipun dia bebas, dia tidak akan membantuku."},{"jp":"彼女は美人なくせに、デートが続かない。","romaji":"Kanojo wa bijin na kuse ni, deeto ga tsudzukanai.","en":"Even though she's beautiful, she can't keep a date going.","id":"Meskipun dia cantik, dia tidak bisa mempertahankan kencannya."}]},{"pattern":"～くらい (〜kurai)","meaning":"Expresses an approximate quantity or degree; 'about', 'approximately', or 'to the extent of'.","meaningId":"Menyatakan perkiraan kuantitas atau derajat; 'tentang', 'kira-kira', atau 'sejauh'.","formation":"Verb-casual + くらい, い-Adjective + くらい, な-Adjective + くらい, Noun + くらい","formationId":"Kata Kerja-kasual + くらい, い-Kata Sifat + くらい, な-Kata Sifat + くらい, Kata Benda + くらい","examples":[{"jp":"１０分くらい待ちましょう。","romaji":"Juppun kurai machimashou.","en":"Let's wait for about 10 minutes.","id":"Mari kita tunggu sekitar 10 menit."},{"jp":"彼女はその映画を５回くらい見ました。","romaji":"Kanojo wa sono eiga wo go-kai kurai mimashita.","en":"She watched that movie about five times.","id":"Dia menonton film itu sekitar lima kali."},{"jp":"その本は面白いくらい難しいです。","romaji":"Sono hon wa omoshiroi kurai muzukashii desu.","en":"That book is so difficult that it’s interesting.","id":"Buku itu sangat sulit sehingga menarik."},{"jp":"この部屋はきれいなくらい広いです。","romaji":"Kono heya wa kirei na kurai hiroi desu.","en":"This room is spacious to the extent of being beautiful.","id":"Ruangan ini luas dan indah."}]},{"pattern":"～くらい～は～ない (〜kurai 〜wa 〜nai)","meaning":"Express the least one can do; 'at least', 'the least', 'no less than'.","meaningId":"Ekspresikan hal yang paling tidak dapat dilakukan seseorang; 'setidaknya', 'setidaknya', 'tidak kurang dari'.","formation":"Verb-casual (non-past) + くらい + は + Verb-casual (negative), Adjective (non-past) + くらい + は + Adjective (negative)","formationId":"Verba-casual (bukan masa lalu) + くらい + は + Verb-casual (negatif), Kata sifat (bukan masa lalu) + くらい + は + Kata sifat (negatif)","examples":[{"jp":"週に一度くらいはジムに行かないと。","romaji":"Shuu ni ichido kurai wa jimu ni ikanai to.","en":"I have to go to the gym at least once a week.","id":"Saya harus pergi ke gym setidaknya seminggu sekali."},{"jp":"毎日くらいは歯を磨かないと。","romaji":"Mainichi kurai wa ha wo migakanai to.","en":"I have to brush my teeth at least every day.","id":"Saya harus menyikat gigi setidaknya setiap hari."},{"jp":"この問題くらいは解決しないと。","romaji":"Kono mondai kurai wa kaiketsu shinai to.","en":"I have to solve at least this problem.","id":"Setidaknya saya harus menyelesaikan masalah ini."},{"jp":"彼女が泣いているくらいなら慰めないと。","romaji":"Kanojo ga naite iru kurai nara nagusamenai to.","en":"If she is crying that much, I should at least try to comfort her.","id":"Jika dia menangis sepuasnya, setidaknya aku harus berusaha menghiburnya."}]},{"pattern":"～こそ (〜koso)","meaning":"Emphasizes the importance or uniqueness of something or someone; 'precisely', 'exactly', 'it is...', 'of all...'.","meaningId":"Menekankan pentingnya atau keunikan sesuatu atau seseorang; 'tepatnya', 'tepatnya', 'itu...', 'semuanya...'.","formation":"Noun + こそ, (Verb-て + こそ)","formationId":"Kata Benda + こそ, (Kata Kerja-て + こそ)","examples":[{"jp":"今日こそ勉強しなければなりません。","romaji":"Kyou koso benkyou shinakereba narimasen.","en":"Today, of all days, I must study.","id":"Hari ini, dari hari-hari lainnya, aku harus belajar."},{"jp":"あなたこそ私の一番の友達です。","romaji":"Anata koso watashi no ichiban no tomodachi desu.","en":"You are precisely my best friend.","id":"Kamu justru sahabatku."},{"jp":"お金がないことこそ幸せの秘訣ではないか。","romaji":"O-kane ga nai koto koso shiawase no hiketsu de wa nai ka.","en":"Isn't not having money exactly the key to happiness?","id":"Bukankah punya uang adalah kunci kebahagiaan?"},{"jp":"彼こそまさにプロの歌手のように歌える。","romaji":"Kare koso masani puro no kashu no you ni utaeru.","en":"He can sing precisely like a professional singer.","id":"Dia bisa menyanyi persis seperti penyanyi profesional."}]},{"pattern":"～こと (〜koto)","meaning":"Express an action in a nominal (noun-like) form or state fact or experience.","meaningId":"Menyatakan suatu tindakan dalam bentuk nominal (seperti kata benda) atau menyatakan fakta atau pengalaman.","formation":"Verb-plain form + こと, Verb-phrase in plain form + こと","formationId":"Kata kerja-bentuk biasa + こと, Frase kata kerja dalam bentuk biasa + こと","examples":[{"jp":"日本語を話すことができます。","romaji":"Nihongo wo hanasu koto ga dekimasu.","en":"I can speak Japanese.","id":"Saya bisa berbicara bahasa Jepang."},{"jp":"毎日運動することは健康に良いです。","romaji":"Mainichi undou suru koto wa kenkou ni ii desu.","en":"Exercising every day is good for your health.","id":"Berolahraga setiap hari baik untuk kesehatan Anda."},{"jp":"彼はピアノを弾くことが大好きです。","romaji":"Kare wa piano wo hiku koto ga daisuki desu.","en":"He loves to play the piano.","id":"Dia suka bermain piano."},{"jp":"映画を見ることに時間を使いたくない。","romaji":"Eiga wo miru koto ni jikan wo tsukai takunai.","en":"I don't want to spend time watching movies.","id":"Saya tidak ingin menghabiskan waktu menonton film."}]},{"pattern":"～ことだ (〜koto da)","meaning":"Expresses advice or recommendation; 'should', 'it is important', 'it is necessary'.","meaningId":"Mengungkapkan saran atau rekomendasi; 'seharusnya', 'itu penting', 'itu perlu'.","formation":"Verb-ますstem + ことだ, い-Adjective + ことだ, な-Adjective + なことだ, Noun + のことだ","formationId":"Kata Kerja-ますbatang + ことだ, い-Kata Sifat + ことだ, な-Kata Sifat + なことだ, Kata Benda + のことだ","examples":[{"jp":"毎日運動することだ。","romaji":"Mainichi undou suru koto da.","en":"You should exercise every day.","id":"Anda harus berolahraga setiap hari."},{"jp":"健康のために、野菜をたくさん食べることだ。","romaji":"Kenkou no tame ni, yasai wo takusan taberu koto da.","en":"For your health, you should eat lots of vegetables.","id":"Untuk kesehatan Anda, Anda harus makan banyak sayuran."},{"jp":"勉強しているとき、静かな場所を選ぶことだ。","romaji":"Benkyou shiteiru toki, shizuka na basho wo erabu koto da.","en":"When studying, you should choose a quiet place.","id":"Saat belajar, sebaiknya pilih tempat yang tenang."},{"jp":"辞書を使って、新しい言葉を覚えることだ。","romaji":"Jisho wo tsukatte, atarashii kotoba wo oboeru koto da.","en":"You should use a dictionary to learn new words.","id":"Anda harus menggunakan kamus untuk mempelajari kata-kata baru."}]},{"pattern":"～ことにしている (〜koto ni shite iru)","meaning":"Express a personal rule or habit; 'I make it a rule to', 'I always make sure to'.","meaningId":"Ekspresikan aturan atau kebiasaan pribadi; 'Saya membuat aturan untuk', 'Saya selalu memastikannya'.","formation":"Verb-casual + ことにしている","formationId":"Kata kerja-kasual + ことにしている","examples":[{"jp":"毎日運動することにしている。","romaji":"Mainichi undou suru koto ni shite iru.","en":"I make it a rule to exercise every day.","id":"Saya membuat aturan untuk berolahraga setiap hari."},{"jp":"夜遅くまで働かないことにしている。","romaji":"Yoru osoku made hatarakanai koto ni shite iru.","en":"I make it a rule not to work late into the night.","id":"Saya membuat peraturan untuk tidak bekerja hingga larut malam."},{"jp":"食事の後、歯を磨くことにしている。","romaji":"Shokuji no ato, ha wo migaku koto ni shite iru.","en":"I always make sure to brush my teeth after meals.","id":"Saya selalu memastikan untuk menyikat gigi setelah makan."},{"jp":"会議には必ず10分前に着くことにしている。","romaji":"Kaigi ni wa kanarazu juppun mae ni tsuku koto ni shite iru.","en":"I always make sure to arrive 10 minutes early for meetings.","id":"Saya selalu memastikan untuk datang 10 menit lebih awal untuk rapat."}]},{"pattern":"～ことになっている (〜koto ni natte iru)","meaning":"Describes something that is decided, arranged, or expected.","meaningId":"Menggambarkan sesuatu yang diputuskan, diatur, atau diharapkan.","formation":"Verb-dictionary form + ことになっている","formationId":"Bentuk kamus kata kerja + ことになっている","examples":[{"jp":"この会社では、20時には仕事を終えることになっている。","romaji":"Kono kaisha de wa, 20-ji ni shigoto o oeru koto ni natte iru.","en":"In this company, it is decided that work will end at 8 pm.","id":"Di perusahaan ini diputuskan pekerjaan akan berakhir pada jam 8 malam."},{"jp":"日本では、18歳以上の人が選挙に投票することになっている。","romaji":"Nihon de wa, 18-sai ijou no hito ga senkyo ni touhyou suru koto ni natte iru.","en":"In Japan, it is decided that people 18 years old and above will vote in elections.","id":"Di Jepang, diputuskan bahwa orang yang berusia 18 tahun ke atas akan memilih dalam pemilu."},{"jp":"学校では、制服を着ることになっている。","romaji":"Gakkou de wa, seifuku o kiru koto ni natte iru.","en":"At school, it is decided that students will wear uniforms.","id":"Di sekolah, diputuskan bahwa siswa akan mengenakan seragam."},{"jp":"田中さんが今回のプロジェクトリーダーになることになっている。","romaji":"Tanaka-san ga konkai no purojekuto riidaa ni naru koto ni natte iru.","en":"It is decided that Tanaka will be the project leader this time.","id":"Diputuskan bahwa Tanaka akan menjadi pemimpin proyek kali ini."}]},{"pattern":"～ことは…が (～koto wa... ga)","meaning":"Indicates that while something may be true or valid, there is another contrasting point.","meaningId":"Menunjukkan bahwa meskipun sesuatu mungkin benar atau valid, ada hal lain yang kontras.","formation":"Verb-casual + ことは + が, い-Adjective + ことは + が, な-Adjective + だ + ことは + が, Noun + だ + ことは + が","formationId":"Kata Kerja-kasual + ことは + が, い-Kata Sifat + ことは + が, な-Kata Sifat + だ + ことは + が, Kata Benda + だ + ことは + が","examples":[{"jp":"この映画は面白いことは面白いが、ちょっと長すぎる。","romaji":"Kono eiga wa omoshiroi koto wa omoshiroi ga, chotto naga-sugiru.","en":"This movie may be interesting, but it is a bit too long.","id":"Film ini mungkin menarik, tapi agak terlalu panjang."},{"jp":"彼は親切なことは親切だが、少し無口だ。","romaji":"Kare wa shinsetsu na koto wa shinsetsu da ga, sukoshi mukuchi da.","en":"He may be kind, but he is a bit quiet.","id":"Dia mungkin baik, tapi dia agak pendiam."},{"jp":"このゲームは難しいことは難しいが、やめられない。","romaji":"Kono geemu wa muzukashii koto wa muzukashii ga, yamerarenai.","en":"This game may be difficult, but I can't stop playing.","id":"Game ini mungkin sulit, tapi saya tidak bisa berhenti memainkannya."},{"jp":"彼女は美しいことは美しいが、ちょっと高飛車だ。","romaji":"Kanojo wa utsukushii koto wa utsukushii ga, chotto koubisha da.","en":"She may be beautiful, but she is a bit arrogant.","id":"Dia mungkin cantik, tapi dia sedikit sombong."}]},{"pattern":"～ことはない (〜koto wa nai)","meaning":"Expresses that something doesn't need to be done or there's no occasion to do it; 'don't have to', 'not necessary'.","meaningId":"Menyatakan bahwa sesuatu tidak perlu dilakukan atau tidak ada kesempatan untuk melakukannya; 'tidak perlu', 'tidak perlu'.","formation":"Verb-dictionary form + ことはない, い-Adjective + ことはない, な-Adjective + であることはない, Noun + であることはない","formationId":"Bentuk kamus kata kerja + ことはない, い-Kata Sifat + ことはない, な-Kata Sifat + であることはない, Kata Benda + であることはない","examples":[{"jp":"お金があるから、無理に貯金することはない。","romaji":"Okane ga aru kara, muri ni chokin suru koto wa nai.","en":"Since I have enough money, there's no need to force myself to save.","id":"Karena saya punya cukup uang, tidak perlu memaksakan diri untuk menabung."},{"jp":"この本は簡単だから、辞書を使うことはない。","romaji":"Kono hon wa kantan dakara, jisho wo tsukau koto wa nai.","en":"Since this book is easy, there's no need to use a dictionary.","id":"Karena buku ini mudah, tidak perlu menggunakan kamus."},{"jp":"彼女は海外旅行に行きたくなければ、行くことはない。","romaji":"Kanojo wa kaigai ryokou ni ikitakunakereba, iku koto wa nai.","en":"If she doesn't want to go on an overseas trip, she doesn't have to go.","id":"Jika dia tidak ingin bepergian ke luar negeri, dia tidak perlu pergi."},{"jp":"寒くなければ、コートを着ることはない。","romaji":"Samukunakereba, kooto wo kiru koto wa nai.","en":"If it's not cold, there's no need to wear a coat.","id":"Kalau tidak dingin, tidak perlu memakai mantel."}]},{"pattern":"～さ (〜sa)","meaning":"Express the degree or extent of a quality; '-ness', 'degree of'.","meaningId":"Menyatakan derajat atau luasnya suatu kualitas; '-ness', 'derajat'.","formation":"い-Adjective (drop い) + さ, な-Adjective + さ","formationId":"い-Kata sifat (jatuhkan い) + さ, な-Kata sifat + さ","examples":[{"jp":"この料理は辛さが強い。","romaji":"Kono ryouri wa karasa ga tsuyoi.","en":"The spiciness of this dish is strong.","id":"Pedasnya masakan ini kuat."},{"jp":"彼女の美しさは皆に憧れられる。","romaji":"Kanojo no utsukushisa wa mina ni akogarerareru.","en":"Her beauty is admired by everyone.","id":"Kecantikannya dikagumi semua orang."},{"jp":"山田さんの親切さで、困っている人を助けてくれる。","romaji":"Yamada-san no shinsetsusa de, komatte iru hito wo tasukete kureru.","en":"Yamada-san's kindness helps people in trouble.","id":"Kebaikan Yamada-san membantu orang yang berada dalam kesulitan."},{"jp":"この部屋の広さは十分だと思う。","romaji":"Kono heya no hirosa wa juubun da to omou.","en":"I think the size of this room is enough.","id":"Saya rasa ukuran ruangan ini cukup."}]},{"pattern":"～さえ","meaning":"Emphasizes a specific item or action; 'even', 'if only', 'as long as'.","meaningId":"Menekankan item atau tindakan tertentu; 'genap', 'kalau saja', 'selama'.","formation":"Noun + さえ, Verb-casual + さえ, い-Adjective + さえ, な-Adjective + でさえ","formationId":"Kata benda + さえ, Kata Kerja-kasual + さえ, い-Kata Sifat + さえ, な-Kata Sifat + でさえ","examples":[{"jp":"お金さえあれば、世界中を旅行できる。","romaji":"Okane sae areba, sekaijuu wo ryokou dekiru.","en":"If only I have money, I can travel around the world.","id":"Kalau saja aku punya uang, aku bisa keliling dunia."},{"jp":"彼は英語さえ話せれば、その仕事ができるだろう。","romaji":"Kare wa eigo sae hanasereba, sono shigoto ga dekiru darou.","en":"As long as he can speak English, he can do that job.","id":"Selama dia bisa berbahasa Inggris, dia bisa melakukan pekerjaan itu."},{"jp":"彼女は頭がいいだけでなく、運動も上手だ。テニスさえできる。","romaji":"Kanojo wa atama ga ii dake denaku, undou mo jouzu da. Tenisu sae dekiru.","en":"Not only is she smart, she is also good at sports. She can even play tennis.","id":"Tidak hanya pintar, dia juga pandai olahraga. Dia bahkan bisa bermain tenis."},{"jp":"明るい場所で本を読むのが好きだ。部屋の電気さえつけなくても大丈夫だ。","romaji":"Akarui basho de hon wo yomu no ga suki da. Heya no denki sae tsukenakute mo daijoubu da.","en":"I like reading books in bright places. I'm fine even if I don't turn on the room light.","id":"Saya suka membaca buku di tempat terang. Aku baik-baik saja meskipun aku tidak menyalakan lampu kamar."}]},{"pattern":"～しかない (〜shika nai)","meaning":"Express the idea of 'only', 'no other option but', 'nothing else but'.","meaningId":"Ekspresikan gagasan 'hanya', 'tidak ada pilihan lain selain', 'tidak ada yang lain selain'.","formation":"Verb-casual + しかない, い-Adjective + しかない, な-Adjective + しかない, Noun + しかない","formationId":"Kata Kerja-kasual + しかない, い-Kata Sifat + しかない, な-Kata Sifat + しかない, Kata Benda + しかない","examples":[{"jp":"この問題を解決する方法は一つしかない。","romaji":"Kono mondai wo kaiketsu suru houhou wa hitotsu shika nai.","en":"There is only one way to solve this problem.","id":"Hanya ada satu cara untuk mengatasi masalah ini."},{"jp":"彼が出て行ったら、泣くしかない。","romaji":"Kare ga dete ittara, naku shika nai.","en":"If he leaves, there's nothing else to do but cry.","id":"Jika dia pergi, tidak ada lagi yang bisa dilakukan selain menangis."},{"jp":"彼女にはあと一月しかない。","romaji":"Kanojo ni wa ato ichigatsu shika nai.","en":"She has only one month left.","id":"Dia hanya punya waktu satu bulan lagi."},{"jp":"僕には君を信じるしかない。","romaji":"Boku ni wa kimi wo shinjiru shika nai.","en":"I have no choice but to trust you.","id":"Aku tidak punya pilihan selain mempercayaimu."}]},{"pattern":"すこしも〜ない","meaning":"Express a negative state or action; 'not at all', 'none whatsoever'.","meaningId":"Ekspresikan keadaan atau tindakan negatif; 'tidak sama sekali', 'tidak ada sama sekali'.","formation":"すこしも + Verb-negative","formationId":"すこしも + Kata kerja-negatif","examples":[{"jp":"彼はすこしも悲しそうに見えません。","romaji":"Kare wa sukoshimo kanashisou ni miemasen.","en":"He doesn't look sad at all.","id":"Dia tidak terlihat sedih sama sekali."},{"jp":"この部屋はすこしも寒くない。","romaji":"Kono heya wa sukoshimo samukunai.","en":"This room is not cold at all.","id":"Ruangan ini sama sekali tidak dingin."},{"jp":"彼女はすこしも心配していない。","romaji":"Kanojo wa sukoshimo shinpai shite inai.","en":"She is not worried at all.","id":"Dia tidak khawatir sama sekali."},{"jp":"まったく知らない人と話すのは怖い。","romaji":"Mattaku shiranai hito to hanasu no wa kowai.","en":"It's scary to talk to someone I don't know at all.","id":"Menakutkan berbicara dengan seseorang yang tidak saya kenal sama sekali."}]},{"pattern":"～ずに (〜zu ni)","meaning":"Express 'without doing' something or 'not doing' something.","meaningId":"Ekspresikan 'tanpa melakukan' sesuatu atau 'tidak melakukan' sesuatu.","formation":"Verb-ない form (Remove ない) + ずに","formationId":"Bentuk kata kerja-ない (Hapus ない) + ずに","examples":[{"jp":"彼は笑わずに話を聞いていました。","romaji":"Kare wa warawazu ni hanashi wo kiiteimashita.","en":"He was listening to the story without laughing.","id":"Dia mendengarkan ceritanya tanpa tertawa."},{"jp":"食べずに寝るのは良くないです。","romaji":"Tabezu ni neru no wa yokunai desu.","en":"It's not good to go to bed without eating.","id":"Tidak baik tidur tanpa makan."},{"jp":"コーヒーを飲まずに仕事を始めました。","romaji":"Koohii wo nomazu ni shigoto wo hajimemashita.","en":"I started working without drinking coffee.","id":"Saya mulai bekerja tanpa minum kopi."},{"jp":"誰にも言わずに出かけました。","romaji":"Dare ni mo iwazu ni dekakemashita.","en":"I went out without telling anyone.","id":"Aku keluar tanpa memberitahu siapa pun."}]},{"pattern":"～せいで (〜sei de)","meaning":"Indicates that something or someone caused an unfortunate result.","meaningId":"Menunjukkan bahwa sesuatu atau seseorang menyebabkan akibat yang tidak menguntungkan.","formation":"Verb-casual + せいで, い-Adjective + せいで, な-Adjective + なせいで, Noun + のせいで","formationId":"Kata Kerja-kasual + せいで, い-Kata Sifat + せいで, な-Kata Sifat + なせいで, Kata Benda + のせいで","examples":[{"jp":"雨のせいで試合が中止になりました。","romaji":"Ame no sei de shiai ga chuushi ni narimashita.","en":"The game was cancelled because of the rain.","id":"Pertandingan dibatalkan karena hujan."},{"jp":"彼の遅刻のせいで、みんな待たされました。","romaji":"Kare no chikoku no sei de, minna matasaremashita.","en":"Everyone had to wait because of his lateness.","id":"Setiap orang harus menunggu karena keterlambatannya."},{"jp":"病気のせいで休日が台無しになった。","romaji":"Byouki no sei de kyuujitsu ga dainashi ni natta.","en":"My holiday was ruined due to illness.","id":"Liburanku hancur karena sakit."},{"jp":"仕事が忙しくて寝不足なせいで、集中できない。","romaji":"Shigoto ga isogashikute nebusoku na sei de, shuuchuu dekinai.","en":"I can't concentrate because I'm sleep-deprived due to busy work.","id":"Saya tidak bisa berkonsentrasi karena kurang tidur akibat kesibukan kerja."}]},{"pattern":"～せてください (〜sete kudasai)","meaning":"Requesting someone to allow or let you do something (causative request).","meaningId":"Meminta seseorang untuk memperbolehkan atau membiarkan Anda melakukan sesuatu (permintaan sebab akibat).","formation":"Verb-causative (させ) + て + ください","formationId":"Kata kerja penyebab (させ) + て + ください","examples":[{"jp":"もう一度説明させてください。","romaji":"Mou ichido setsumei sasete kudasai.","en":"Please let me explain it once more.","id":"Tolong izinkan saya menjelaskannya sekali lagi."},{"jp":"帰らせてください。","romaji":"Kaerasete kudasai.","en":"Please let me go home.","id":"Tolong biarkan aku pulang."},{"jp":"その本を見せてください。","romaji":"Sono hon o misete kudasai.","en":"Please let me see that book.","id":"Tolong izinkan saya melihat buku itu."},{"jp":"ここで待たせてください。","romaji":"Koko de matasete kudasai.","en":"Please let me wait here.","id":"Tolong biarkan aku menunggu di sini."}]},{"pattern":"～そのために (〜sono tame ni)","meaning":"For the purpose of; because of; in order to.","meaningId":"Untuk tujuan; karena; untuk.","formation":"Sentence/phrase 1 + そのために + Sentence/phrase 2","formationId":"Kalimat/frasa 1 + そのために + Kalimat/frasa 2","examples":[{"jp":"試験に合格するために、毎日勉強しています。そのために、早く寝て早く起きるようにしています。","romaji":"Shiken ni goukaku suru tame ni, mainichi benkyou shiteimasu. Sono tame ni, hayaku nete hayaku okiru you ni shiteimasu.","en":"I study every day to pass the exam. For that reason, I go to bed early and wake up early.","id":"Saya belajar setiap hari untuk lulus ujian. Oleh karena itu, saya tidur lebih awal dan bangun lebih awal."},{"jp":"健康的な生活を送りたい。そのために、ジムに通って運動しています。","romaji":"Kenkouteki na seikatsu wo okuritai. Sono tame ni, jimu ni kayotte undou shiteimasu.","en":"I want to lead a healthy lifestyle. For that reason, I go to the gym and exercise.","id":"Saya ingin menjalani gaya hidup sehat. Oleh karena itu, saya pergi ke gym dan berolahraga."},{"jp":"環境を守るために、リサイクルに取り組んでいます。そのために、ゴミを分別して捨てています。","romaji":"Kankyou wo mamoru tame ni, risaikuru ni torikundeimasu. Sono tame ni, gomi wo bunbetsu shite suteteimasu.","en":"I'm working on recycling to protect the environment. Therefore, I separate and dispose of trash properly.","id":"Saya sedang melakukan daur ulang untuk melindungi lingkungan. Oleh karena itu, saya memilah dan membuang sampah dengan baik."},{"jp":"新しい仕事を見つけたい。そのために、履歴書を書いて応募しています。","romaji":"Atarashii shigoto wo mitsuketai. Sono tame ni, rirekisho wo kaite oubo shiteimasu.","en":"I want to find a new job. So, I'm writing my resume and applying.","id":"Saya ingin mencari pekerjaan baru. Jadi, saya menulis resume saya dan melamar."}]},{"pattern":"～その結果 (〜sono kekka)","meaning":"Shows the result or consequence of a previous action or situation; 'as a result', 'in consequence'.","meaningId":"Menunjukkan hasil atau akibat dari tindakan atau situasi sebelumnya; 'akibatnya', 'akibatnya'.","formation":"Situation/ACTION 1 + その結果 + RESULT","formationId":"Situasi/AKSI 1 + その結果 + HASIL","examples":[{"jp":"彼女は毎日練習した。その結果、試合に勝った。","romaji":"Kanojo wa mainichi renshuu shita. Sono kekka, shiai ni katta.","en":"She practiced every day. As a result, she won the match.","id":"Dia berlatih setiap hari. Hasilnya, dia memenangkan pertandingan."},{"jp":"会社が倒産した。その結果、彼は仕事を失った。","romaji":"Kaisha ga tousan shita. Sono kekka, kare wa shigoto wo ushinatta.","en":"The company went bankrupt. As a result, he lost his job.","id":"Perusahaan bangkrut. Akibatnya, dia kehilangan pekerjaan."},{"jp":"私たちは遅刻した。その結果、電車に乗れなかった。","romaji":"Watashitachi wa chikoku shita. Sono kekka, densha ni norenakatta.","en":"We were late. As a result, we couldn't catch the train.","id":"Kami terlambat. Akibatnya, kami tidak bisa naik kereta."},{"jp":"彼は勉強を怠った。その結果、試験に落ちた。","romaji":"Kare wa benkyou wo okotatta. Sono kekka, shiken ni ochita.","en":"He neglected his studies. As a result, he failed the exam.","id":"Dia mengabaikan studinya. Akibatnya, dia gagal dalam ujian."}]},{"pattern":"～それと～ (〜sore to〜)","meaning":"Used to link two or more items; 'and', 'also'.","meaningId":"Digunakan untuk menghubungkan dua item atau lebih; 'dan', 'juga'.","formation":"Item1 + それと + Item2","formationId":"Barang1 + Barang + Barang2","examples":[{"jp":"買い物に行くつもりです。それと、郵便局にも行かなくては。","romaji":"Kaimono ni iku tsumori desu. Sore to, yuubinkyoku ni mo ikanakute wa.","en":"I plan to go shopping, and I also have to go to the post office.","id":"Saya berencana untuk pergi berbelanja, dan saya juga harus pergi ke kantor pos."},{"jp":"今日はタコスを作りました。それと、サラダも作りました。","romaji":"Kyou wa takosu wo tsukurimashita. Sore to, sarada mo tsukurimashita.","en":"Today, I made tacos, and I also made a salad.","id":"Hari ini, saya membuat taco, dan saya juga membuat salad."},{"jp":"出かける前に、部屋を掃除してください。それと、ゴミを捨ててください。","romaji":"Dekakeru mae ni, heya wo souji shite kudasai. Sore to, gomi wo sutete kudasai.","en":"Please clean the room before you go out, and also throw away the trash.","id":"Harap bersihkan kamar sebelum Anda keluar, dan buang juga sampahnya."},{"jp":"彼はフランス語が話せます。それと、スペイン語も話せます。","romaji":"Kare wa furansugo ga hanasemasu. Sore to, supeingo mo hanasemasu.","en":"He can speak French, and he can also speak Spanish.","id":"Dia bisa berbahasa Prancis, dan dia juga bisa berbahasa Spanyol."}]},{"pattern":"～？それとも～？ (～? sore tomo ～?)","meaning":"Presents two alternatives or choices; 'or', 'either...or'.","meaningId":"Menyajikan dua alternatif atau pilihan; 'atau', 'salah satu...atau'.","formation":"Verb-casual + ？それとも + Verb-casual + ？, etc.","formationId":"Kata kerja-kasual + ？それとも + Kata kerja-kasual + ？, dan seterusnya.","examples":[{"jp":"コーヒーを飲む？それとも紅茶を飲む？","romaji":"Koohii o nomu? Sore tomo koucha o nomu?","en":"Do you want to drink coffee? Or tea?","id":"Apakah Anda ingin minum kopi? Atau teh?"},{"jp":"この映画は面白い？それともつまらない？","romaji":"Kono eiga wa omoshiroi? Sore tomo tsumaranai?","en":"Is this movie interesting? Or is it boring?","id":"Apakah film ini menarik? Atau membosankan?"},{"jp":"彼は日本人だ？それとも外国人だ？","romaji":"Kare wa nihonjin da? Sore tomo gaikokujin da?","en":"Is he Japanese? Or is he a foreigner?","id":"Apakah dia orang Jepang? Atau dia orang asing?"},{"jp":"寿司を食べに行く？それともラーメンを食べに行く？","romaji":"Sushi o tabe ni iku? Sore tomo raamen o tabe ni iku?","en":"Are we going to eat sushi? Or are we going to eat ramen?","id":"Apakah kita akan makan sushi? Atau apakah kita akan makan ramen?"}]},{"pattern":"～だけしか","meaning":"Emphasizes the scarcity or insufficiency of something; 'only', 'nothing but'.","meaningId":"Menekankan kelangkaan atau kekurangan sesuatu; 'hanya', 'tidak lain hanyalah'.","formation":"Noun/Quantity + だけ + しか + Negative Verb","formationId":"Kata Benda/Jumlah + だけ + しか + Kata Kerja Negatif","examples":[{"jp":"今日は1時間だけしか勉強できなかった。","romaji":"Kyou wa ichijikan dake shika benkyou dekinakatta.","en":"Today, I could study for only one hour.","id":"Hari ini, saya hanya bisa belajar selama satu jam."},{"jp":"彼はカレーだけしか食べない。","romaji":"Kare wa karee dake shika tabenai.","en":"He eats only curry.","id":"Dia hanya makan kari."},{"jp":"田中さんは5人だけしか招待しなかった。","romaji":"Tanaka-san wa gonin dake shika shoutai shinakatta.","en":"Tanaka only invited five people.","id":"Tanaka hanya mengundang lima orang."},{"jp":"あのレストランでは野菜だけしか売っていない。","romaji":"Ano resutoran de wa yasai dake shika utte inai.","en":"That restaurant sells only vegetables.","id":"Restoran itu hanya menjual sayuran."}]},{"pattern":"だけど","meaning":"Expresses a contrast or contradiction; 'but', 'however', 'even though'.","meaningId":"Mengekspresikan kontras atau kontradiksi; 'tetapi', 'namun', 'meskipun'.","formation":"Sentence 1 + だけど + Sentence 2, or Sentence 1 + 。だけど、Sentence 2","formationId":"Kalimat 1 + だけど + Kalimat 2, atau Kalimat 1 + 。だけど、Kalimat 2","examples":[{"jp":"試験に合格したけど、まだ勉強しなければならない。","romaji":"Shiken ni goukaku shita kedo, mada benkyou shinakereba naranai.","en":"I passed the exam, but I still have to study.","id":"Saya lulus ujian, tetapi saya masih harus belajar."},{"jp":"この部屋は広いけど、家賃が高いです。","romaji":"Kono heya wa hiroi kedo, yachin ga takai desu.","en":"This room is spacious, but the rent is high.","id":"Kamar ini luas, tapi harga sewanya tinggi."},{"jp":"彼は優しいけど、時々厳しいです。","romaji":"Kare wa yasashii kedo, tokidoki kibishii desu.","en":"He is kind, but sometimes strict.","id":"Dia baik, tapi terkadang tegas."},{"jp":"朝ごはんは作りたいけど、時間がない。","romaji":"Asagohan wa tsukuritai kedo, jikan ga nai.","en":"I want to make breakfast, but there's no time.","id":"Aku ingin membuat sarapan, tapi tidak ada waktu."}]},{"pattern":"～たて","meaning":"Indicates an action that has just been completed; 'freshly', 'just'.","meaningId":"Indicates an action that has just been completed; 'baru', 'hanya'.","formation":"Verb-stem + たて","formationId":"Batang kata kerja + たて","examples":[{"jp":"このパンは焼きたてで、まだ温かいです。","romaji":"Kono pan wa yakitate de, mada atatakai desu.","en":"This bread is freshly baked and still warm.","id":"Roti ini baru dipanggang dan masih hangat."},{"jp":"作りたてのお弁当が美味しい。","romaji":"Tsukuritate no obentou ga oishii.","en":"A freshly made bento is delicious.","id":"Bento yang baru dibuat memang enak."},{"jp":"洗いたてのシャツはいい匂いがする。","romaji":"Araitate no shatsu wa ii nioi ga suru.","en":"Freshly washed shirts smell nice.","id":"Kemeja yang baru dicuci berbau harum."},{"jp":"彼女は切りたての野菜をサラダに入れました。","romaji":"Kanojo wa kiritate no yasai wo sarada ni iremashita.","en":"She added freshly cut vegetables to the salad.","id":"Dia menambahkan sayuran yang baru dipotong ke dalam salad."}]},{"pattern":"～たとえ～ても (〜tatoe〜temo)","meaning":"Express a condition with 'even if'; 'no matter how'.","meaningId":"Nyatakan suatu kondisi dengan 'sekalipun'; 'bagaimanapun caranya'.","formation":"たとえ + Verb-casual + ても, たとえ + い-Adjective + くても, たとえ + な-Adjective + であっても, たとえ + Noun + であっても","formationId":"たとえ + Verba-kasual + ても, たとえ + い-Kata Sifat + くても, たとえ + な-Kata Sifat + であっても, たとえ + Kata Benda +であっても","examples":[{"jp":"たとえ雨が降っても、出かけましょう。","romaji":"Tatoe ame ga futte mo, dekakemashou.","en":"Even if it rains, let's go out.","id":"Meski hujan, ayo keluar."},{"jp":"たとえ彼が怒っても、本当のことを言いましょう。","romaji":"Tatoe kare ga okotte mo, hontou no koto wo iimashou.","en":"Even if he gets angry, let's tell the truth.","id":"Bahkan jika dia marah, katakan yang sebenarnya."},{"jp":"たとえ寒くても、散歩に行きたい。","romaji":"Tatoe samukute mo, sanpo ni ikitai.","en":"Even if it's cold, I want to go for a walk.","id":"Meski dingin, aku ingin jalan-jalan."},{"jp":"たとえ彼が有名であっても、彼には興味がありません。","romaji":"Tatoe kare ga yuumei de attemo, kare ni wa kyoumi ga arimasen.","en":"Even if he's famous, I'm not interested in him.","id":"Meskipun dia terkenal, aku tidak tertarik padanya."}]},{"pattern":"～たところ (〜ta tokoro)","meaning":"Expresses the result or outcome of an action; 'after', 'just when', 'upon'.","meaningId":"Mengekspresikan hasil atau hasil dari suatu tindakan; 'setelah', 'saat', 'setelah'.","formation":"Verb-た form + ところ","formationId":"Bentuk kata kerja-た + ところ","examples":[{"jp":"宿題をしたところ、先生からもう一つ課題が出された。","romaji":"Shukudai wo shita tokoro, sensei kara mou hitotsu kadai ga dasareta.","en":"Just when I finished my homework, the teacher gave us another assignment.","id":"Tepat ketika saya menyelesaikan pekerjaan rumah saya, guru memberi kami tugas lain."},{"jp":"友達に会ったところ、彼が海外に行くと言った。","romaji":"Tomodachi ni atta tokoro, kare ga kaigai ni iku to itta.","en":"Upon meeting my friend, he told me he's going abroad.","id":"Saat bertemu teman saya, dia memberi tahu saya bahwa dia akan pergi ke luar negeri."},{"jp":"食事を食べ終わったところ、電話がかかってきた。","romaji":"Shokuji wo tabeowatta tokoro, denwa ga kakatte kita.","en":"Just when I finished eating, I got a phone call.","id":"Tepat ketika saya selesai makan, saya mendapat panggilan telepon."},{"jp":"机を整理したところ、忘れていたメモが見つかった。","romaji":"Tsukue wo seiri shita tokoro, wasureteita memo ga mitsukatta.","en":"After organizing my desk, I found a memo I had forgotten about.","id":"Setelah mengatur mejaku, aku menemukan sebuah memo yang telah aku lupakan."}]},{"pattern":"～たとたん (〜ta totan)","meaning":"Express the moment something happens; 'as soon as', 'the moment', 'the instant'.","meaningId":"Ekspresikan saat sesuatu terjadi; 'segera', 'saat ini', 'saat itu juga'.","formation":"Verb-た form + とたん","formationId":"Bentuk kata kerja-た + とたん","examples":[{"jp":"ドアを開けたとたん、猫が逃げ出した。","romaji":"Doa wo aketa totan, neko ga nigedashita.","en":"As soon as I opened the door, the cat ran away.","id":"Begitu saya membuka pintu, kucing itu lari."},{"jp":"電話をかけたとたん、電池が切れた。","romaji":"Denwa wo kaketa totan, denchi ga kireta.","en":"The moment I made the phone call, the battery died.","id":"Saat saya menelepon, baterainya mati."},{"jp":"雨が降り始めたとたん、みんなが傘をさした。","romaji":"Ame ga furihajimeta totan, minna ga kasa wo sashita.","en":"The instant it started raining, everyone put up their umbrellas.","id":"Begitu hujan mulai turun, semua orang memasang payung mereka."},{"jp":"彼に会ったとたん、彼の笑顔が消えた。","romaji":"Kare ni atta totan, kare no egao ga kieta.","en":"As soon as he met me, his smile disappeared.","id":"Begitu dia bertemu denganku, senyumnya menghilang."}]},{"pattern":"～たびに (〜tabi ni)","meaning":"Express 'every time' or 'whenever'.","meaningId":"Ekspresikan 'setiap saat' atau 'kapan saja'.","formation":"Verb-dictionary form + たびに, Noun + のたびに","formationId":"Bentuk kamus kata kerja + たびに, Kata Benda + のたびに","examples":[{"jp":"彼女に会うたびに、心が弾む。","romaji":"Kanojo ni au tabi ni, kokoro ga hazumu.","en":"Every time I meet her, my heart leaps.","id":"Setiap kali aku bertemu dengannya, hatiku berdebar kencang."},{"jp":"雨が降るたびに、懐かしい思い出がよみがえる。","romaji":"Ame ga furu tabi ni, natsukashii omoide ga yomigaeru.","en":"Whenever it rains, nostalgic memories come back.","id":"Setiap kali hujan turun, kenangan nostalgia kembali muncul."},{"jp":"この歌を聴くたびに、幸せな気分になる。","romaji":"Kono uta wo kiku tabi ni, shiawase na kibun ni naru.","en":"Every time I listen to this song, I feel happy.","id":"Setiap kali saya mendengarkan lagu ini, saya merasa senang."},{"jp":"家に帰るたびに、猫が出迎えてくれる。","romaji":"Ie ni kaeru tabi ni, neko ga demukaete kureru.","en":"Every time I return home, the cat greets me.","id":"Setiap kali saya pulang ke rumah, kucing itu menyapa saya."}]},{"pattern":"～だものだ (〜da mono da)","meaning":"Express the reason or cause, often used to justify something.","meaningId":"Mengungkapkan alasan atau sebab, sering digunakan untuk membenarkan sesuatu.","formation":"Verb-casual + んだものだ, い-Adjective + んだものだ, な-Adjective + なんだものだ, Noun + なんだものだ (often with から as んだものだから)","formationId":"Kata Kerja-kasual + んだものだ, い-Kata Sifat + んだものだ, な-Kata Sifat + なんだものだ, Kata Benda + なんだものだ (sering dengan から sebagaiんだものだから)","examples":[{"jp":"疲れたんだものだから、休みたい。","romaji":"Tsukareta n da mono da kara, yasumitai.","en":"I want to rest because I'm tired.","id":"Aku ingin istirahat karena aku lelah."},{"jp":"お腹が空いたんだものだから、何か食べたい。","romaji":"Onaka ga suita n da mono da kara, nanika tabetai.","en":"I want to eat something because I'm hungry.","id":"Aku ingin makan sesuatu karena aku lapar."},{"jp":"忙しいんだものだから、来られない。","romaji":"Isogashii n da mono da kara, korarenai.","en":"I can't come because I'm busy.","id":"Saya tidak bisa datang karena saya sibuk."},{"jp":"彼は親切なんだものだから、誰も彼が好きだ。","romaji":"Kare wa shinsetsu na n da mono da kara, dare mo kare ga suki da.","en":"Everyone likes him because he is kind.","id":"Semua orang menyukainya karena dia baik."}]},{"pattern":"～ちゃった (〜chatta)","meaning":"Express an unintentional action or a regretful action; 'ended up doing', 'did accidentally'.","meaningId":"Menyatakan tindakan yang tidak disengaja atau tindakan yang disesalkan; 'akhirnya melakukan', 'melakukan secara tidak sengaja'.","formation":"Verb-て/で form → ちゃった/じゃった (e.g. 食べてしまった → 食べちゃった)","formationId":"Bentuk kata kerja-て/で → ちゃった/じゃった (misalnya 食べてしまった → 食べちゃった)","examples":[{"jp":"忘れ物をしちゃった。","romaji":"Wasuremono o shichatta.","en":"I accidentally left something behind.","id":"Saya tidak sengaja meninggalkan sesuatu."},{"jp":"寝坊して遅刻しちゃった。","romaji":"Nebou shite chikoku shichatta.","en":"I overslept and ended up being late.","id":"Saya ketiduran dan akhirnya terlambat."},{"jp":"ケーキを全部食べちゃった。","romaji":"Keeki o zenbu tabechatta.","en":"I ended up eating the whole cake.","id":"Saya akhirnya memakan seluruh kuenya."},{"jp":"言わないつもりだったけど、言っちゃった。","romaji":"Iwanai tsumori datta kedo, icchatta.","en":"I wasn't planning to say it, but I ended up saying it.","id":"Aku tidak berencana mengatakannya, tapi akhirnya aku mengatakannya."}]},{"pattern":"～ついでに (〜tsuide ni)","meaning":"Do something while or after completing another action; 'while', 'by the way'.","meaningId":"Melakukan sesuatu saat atau setelah menyelesaikan tindakan lain; 'sementara', 'ngomong-ngomong'.","formation":"Verb (dictionary or た-form) + ついでに, Noun + の + ついでに, or Verb-て form + いる + ついでに","formationId":"Kata Kerja (kamus atau bentuk た) + ついでに, Kata Benda + の + ついでに, atau Bentuk Kata Kerja-て + いる + ついでに","examples":[{"jp":"買い物に行くついでに、郵便局で手紙を出しましょう。","romaji":"Kaimono ni iku tsuide ni, yuubinkyoku de tegami wo dashimashou.","en":"Let's drop off a letter at the post office while going shopping.","id":"Mari kita mengantarkan surat ke kantor pos sambil berbelanja."},{"jp":"図書館で本を借りたついでに、友達に会いました。","romaji":"Toshokan de hon wo karita tsuide ni, tomodachi ni aimashita.","en":"I met my friend while borrowing a book from the library.","id":"Saya bertemu teman saya saat meminjam buku dari perpustakaan."},{"jp":"日本に来たついでに、有名な観光地を訪れたいです。","romaji":"Nihon ni kita tsuide ni, yuumei na kankouchi wo otozuretai desu.","en":"While visiting Japan, I'd like to see some famous tourist spots.","id":"Saat berkunjung ke Jepang, saya ingin melihat beberapa tempat wisata terkenal."},{"jp":"映画館に行ったついでに、新作のポスターを見ました。","romaji":"Eigakan ni itta tsuide ni, shinsaku no posutaa wo mimashita.","en":"While going to the movie theater, I saw a poster for a new film.","id":"Saat pergi ke bioskop, saya melihat poster film baru."}]},{"pattern":"～っけ？ (〜kke?)","meaning":"Used to express that one is trying to recall some information.","meaningId":"Digunakan untuk menyatakan bahwa seseorang sedang mencoba mengingat beberapa informasi.","formation":"Verb-casual + っけ?, い-Adjective + かったっけ?, な-Adjective/Noun + だっけ?","formationId":"Kata Kerja-kasual + っけ?, い-Kata Sifat + かったっけ?, な-Kata Sifat/Kata Benda + だっけ?","examples":[{"jp":"彼は何時に来るっけ？","romaji":"Kare wa nanji ni kuru kke?","en":"What time is he coming again?","id":"Jam berapa dia datang lagi?"},{"jp":"この映画、面白かったっけ？","romaji":"Kono eiga, omoshirokatta kke?","en":"Was this movie interesting?","id":"Apakah film ini menarik?"},{"jp":"彼女は学生だっけ？","romaji":"Kanojo wa gakusei dakke?","en":"She was a student, right?","id":"Dia seorang pelajar, kan?"},{"jp":"すし屋はどこだっけ？","romaji":"Sushiya wa doko dakke?","en":"Where was the sushi place again?","id":"Dimana tempat sushinya lagi?"}]},{"pattern":"～っぱい (〜ppai)","meaning":"Expresses fullness or completeness; 'full', 'full of', 'filled with'.","meaningId":"Mengekspresikan kepenuhan atau kelengkapan; 'penuh', 'penuh', 'diisi dengan'.","formation":"Noun + で + いっぱい (Note: written as いっぱい, read as 'ippai')","formationId":"Kata benda + で + いっぱい (Catatan: ditulis いっぱい, dibaca 'ippai')","examples":[{"jp":"部屋が荷物でいっぱいです。","romaji":"Heya ga nimotsu de ippai desu.","en":"The room is full of luggage.","id":"Ruangan itu penuh dengan barang bawaan."},{"jp":"彼女は笑顔でいっぱいでした。","romaji":"Kanojo wa egao de ippai deshita.","en":"She was full of smiles.","id":"Dia penuh senyum."},{"jp":"彼は仕事でいっぱいです。","romaji":"Kare wa shigoto de ippai desu.","en":"He is completely busy with work.","id":"Dia benar-benar sibuk dengan pekerjaan."},{"jp":"公園は花でいっぱいです。","romaji":"Kouen wa hana de ippai desu.","en":"The park is filled with flowers.","id":"Taman itu penuh dengan bunga."}]},{"pattern":"～っぱなし (〜ppanashi)","meaning":"Indicate a state where an action is left as is (unchanged or unfinished).","meaningId":"Menunjukkan keadaan di mana suatu tindakan dibiarkan apa adanya (tidak diubah atau belum selesai).","formation":"Verb-ますstem + っぱなし","formationId":"Kata kerja-ますbatang + っぱなし","examples":[{"jp":"窓を開けっぱなしにすると、虫が入ってくる。","romaji":"Mado o akeppanashi ni suru to, mushi ga haitte kuru.","en":"If you leave the window open, bugs will come in.","id":"Jika Anda membiarkan jendela terbuka, bug akan masuk."},{"jp":"洗濯物を干しっぱなしで、雨に濡れた。","romaji":"Sentakumono o hoshippanashi de, ame ni nureta.","en":"I left the laundry hanging out, and it got wet in the rain.","id":"Saya meninggalkan cucian di luar, dan basah kuyup karena hujan."},{"jp":"彼はドアを開けっぱなしにして出かけた。","romaji":"Kare wa doa o akeppanashi ni shite dekaketa.","en":"He went out leaving the door open.","id":"Dia keluar meninggalkan pintu terbuka."},{"jp":"テレビをつけっぱなしにして寝てしまった。","romaji":"Terebi o tsukeppanashi ni shite nete shimatta.","en":"I fell asleep with the TV left on.","id":"Saya tertidur dengan TV menyala."}]},{"pattern":"～つまり (〜tsumari)","meaning":"Summarizing, restating, or clarifying a point: 'in other words', 'that is to say'.","meaningId":"Meringkas, menyatakan kembali, atau memperjelas suatu hal: 'dengan kata lain', 'artinya'.","formation":"Sentence A + つまり + Sentence B (rephrasing)","formationId":"Kalimat A + つまり + Kalimat B (pengungkapan ulang)","examples":[{"jp":"彼は大学の教授です。つまり、専門家です。","romaji":"Kare wa daigaku no kyouju desu. Tsumari, senmonka desu.","en":"He is a university professor. In other words, he is an expert.","id":"Dia adalah seorang profesor universitas. Dengan kata lain, dia adalah seorang ahli."},{"jp":"今日は土曜日だ。つまり、明日は日曜日だ。","romaji":"Kyou wa doyoubi da. Tsumari, ashita wa nichiyoubi da.","en":"Today is Saturday. That is to say, tomorrow is Sunday.","id":"Hari ini Sabtu. Artinya, besok adalah hari Minggu."},{"jp":"山田さんは友達のお姉さんです。つまり、私たちの知り合いです。","romaji":"Yamada-san wa tomodachi no oneesan desu. Tsumari, watashitachi no shiriai desu.","en":"Ms. Yamada is my friend's older sister. In short, she's someone we know.","id":"Nona Yamada adalah kakak perempuan temanku. Singkatnya, dia adalah seseorang yang kita kenal."},{"jp":"彼女はフランス出身です。つまり、フランス語が話せます。","romaji":"Kanojo wa Furansu shusshin desu. Tsumari, Furansugo ga hanasemasu.","en":"She is from France. In other words, she can speak French.","id":"Dia berasal dari Perancis. Dengan kata lain, dia bisa berbahasa Prancis."}]},{"pattern":"～つもりでした (〜tsumori deshita)","meaning":"Expressing a past intention or plan; 'was planning to', 'meant to'.","meaningId":"Mengekspresikan niat atau rencana masa lalu; 'berencana untuk', 'bermaksud untuk'.","formation":"Verb-casual (dictionary form) + つもりでした","formationId":"Kata kerja-kasual (bentuk kamus) + つもりでした","examples":[{"jp":"昨日は友達に会うつもりでしたが、風邪を引いてしまいました。","romaji":"Kinou wa tomodachi ni au tsumori deshita ga, kaze o hiite shimaimashita.","en":"I was planning to meet my friend yesterday, but I caught a cold.","id":"Saya berencana untuk bertemu teman saya kemarin, tetapi saya masuk angin."},{"jp":"映画を見るつもりでしたが、時間がなくなりました。","romaji":"Eiga o miru tsumori deshita ga, jikan ga nakunarimashita.","en":"I intended to watch a movie, but I ran out of time.","id":"Saya bermaksud menonton film, tetapi saya kehabisan waktu."},{"jp":"彼らが来るつもりでしたが、電話でキャンセルされました。","romaji":"Karera ga kuru tsumori deshita ga, denwa de kyanseru saremashita.","en":"They were supposed to come, but they canceled by phone.","id":"Mereka seharusnya datang, tapi mereka membatalkannya melalui telepon."},{"jp":"この本を読むつもりでしたが、もう読み終わっていました。","romaji":"Kono hon o yomu tsumori deshita ga, mou yomiowatte imashita.","en":"I meant to read this book, but I realized I'd already finished it.","id":"Aku bermaksud membaca buku ini, tapi aku sadar aku sudah menyelesaikannya."}]},{"pattern":"～てくれと (〜te kureto)","meaning":"Quote someone's request (telling someone to do something).","meaningId":"Mengutip permintaan seseorang (menyuruh seseorang melakukan sesuatu).","formation":"Verb-て form + くれと (言う / 頼む / 伝える, etc.)","formationId":"Bentuk kata kerja-て + くれと (言う / 頼む / 伝える, dll.)","examples":[{"jp":"電話をかけてくれと言われました。","romaji":"Denwa o kakete kureto iwaremashita.","en":"I was told to make a phone call.","id":"Saya disuruh menelepon."},{"jp":"この荷物を運んでくれと頼まれました。","romaji":"Kono nimotsu o hakonde kureto tanomaremashita.","en":"I was asked to carry this luggage.","id":"Saya diminta untuk membawa barang bawaan ini."},{"jp":"最後まで待ってくれとお願いされました。","romaji":"Saigo made matte kureto onegai saremashita.","en":"I was asked to wait until the end.","id":"Saya diminta menunggu sampai akhir."},{"jp":"休んでくれと言われました。","romaji":"Yasunde kureto iwaremashita.","en":"I was told to please take a rest.","id":"Saya disuruh istirahat."}]},{"pattern":"～てごらん (〜te goran)","meaning":"Suggest or invite someone to try doing something; 'Why don't you try...'.","meaningId":"Menyarankan atau mengundang seseorang untuk mencoba melakukan sesuatu; 'Mengapa kamu tidak mencoba...'.","formation":"Verb-て form + ごらん","formationId":"Bentuk kata kerja-て + ごらん","examples":[{"jp":"そのゲームをやってごらん。","romaji":"Sono geemu o yatte goran.","en":"Why don't you try playing that game?","id":"Mengapa Anda tidak mencoba memainkan permainan itu?"},{"jp":"彼に話してごらん。","romaji":"Kare ni hanashite goran.","en":"Try talking to him.","id":"Cobalah berbicara dengannya."},{"jp":"新しいレシピを作ってごらん。","romaji":"Atarashii reshipi o tsukutte goran.","en":"Why don't you try making a new recipe?","id":"Mengapa Anda tidak mencoba membuat resep baru?"},{"jp":"そのドレスを着てごらん。","romaji":"Sono doresu o kite goran.","en":"Try putting on that dress.","id":"Coba kenakan gaun itu."}]},{"pattern":"ですから～","meaning":"Expresses reason or cause; 'because', 'since', 'so'.","meaningId":"Mengungkapkan alasan atau sebab; 'karena', 'sejak', 'jadi'.","formation":"Sentence A + ですから + Sentence B","formationId":"Kalimat A + ですから + Kalimat B","examples":[{"jp":"今日は寒いですから、コートを着てください。","romaji":"Kyou wa samui desu kara, kooto o kite kudasai.","en":"It's cold today, so please wear a coat.","id":"Hari ini dingin, jadi tolong kenakan mantel."},{"jp":"この映画は面白いですから、ぜひ見てください。","romaji":"Kono eiga wa omoshiroi desu kara, zehi mite kudasai.","en":"This movie is interesting, so please watch it.","id":"Film ini menarik, jadi silakan tonton."},{"jp":"明日は休みですから、ゆっくり休んでください。","romaji":"Ashita wa yasumi desu kara, yukkuri yasunde kudasai.","en":"Tomorrow is a day off, so please take your time to rest.","id":"Besok adalah hari libur, jadi harap luangkan waktu Anda untuk istirahat."},{"jp":"彼は親切ですから、手伝ってくれるでしょう。","romaji":"Kare wa shinsetsu desu kara, tetsudatte kureru deshou.","en":"He's kind, so he'll probably help you.","id":"Dia baik, jadi dia mungkin akan membantumu."}]},{"pattern":"～てはじめて (〜te hajimete)","meaning":"Realization or action done for the first time; 'only after', 'not until'.","meaningId":"Realisasi atau tindakan yang dilakukan pertama kali; 'hanya setelah', 'tidak sampai'.","formation":"Verb-て form + はじめて","formationId":"Bentuk kata kerja-て + はじめて","examples":[{"jp":"海外に行ってはじめて、日本の良さが分かりました。","romaji":"Kaigai ni itte hajimete, Nihon no yosa ga wakarimashita.","en":"Only after going abroad did I realize how great Japan is.","id":"Baru setelah pergi ke luar negeri saya menyadari betapa hebatnya Jepang."},{"jp":"彼女と別れてはじめて、彼女の大切さに気づいた。","romaji":"Kanojo to wakarete hajimete, kanojo no taisetsusa ni kizuita.","en":"I realized her importance only after breaking up with her.","id":"Saya menyadari pentingnya dia hanya setelah putus dengannya."},{"jp":"大学を卒業してはじめて、学生時代の楽しさが分かった。","romaji":"Daigaku o sotsugyou shite hajimete, gakusei jidai no tanoshisa ga wakatta.","en":"I understood how fun my student days were only after graduating from university.","id":"Saya mengerti betapa menyenangkannya masa-masa mahasiswa saya hanya setelah lulus dari universitas."},{"jp":"子供ができてはじめて、親の気持ちが分かった。","romaji":"Kodomo ga dekite hajimete, oya no kimochi ga wakatta.","en":"I understood how parents feel only after I had a child.","id":"Saya mengerti bagaimana perasaan orang tua hanya setelah saya memiliki anak."}]},{"pattern":"～てほしい (〜te hoshii)","meaning":"Express a desire for someone else to do something; 'I want you to do...'.","meaningId":"Ekspresikan keinginan agar orang lain melakukan sesuatu; 'Aku ingin kamu melakukan...'.","formation":"Verb-て form + ほしい","formationId":"Bentuk kata kerja-て + ほしい","examples":[{"jp":"子供にもっと勉強してほしい。","romaji":"Kodomo ni motto benkyou shite hoshii.","en":"I want my child to study more.","id":"Saya ingin anak saya belajar lebih banyak."},{"jp":"彼に私に電話してほしい。","romaji":"Kare ni watashi ni denwa shite hoshii.","en":"I want him to call me.","id":"Aku ingin dia meneleponku."},{"jp":"友達に手伝ってほしい。","romaji":"Tomodachi ni tetsudatte hoshii.","en":"I want my friend to help me.","id":"Saya ingin teman saya membantu saya."},{"jp":"彼女に明日ここに来てほしい。","romaji":"Kanojo ni ashita koko ni kite hoshii.","en":"I want her to come here tomorrow.","id":"Saya ingin dia datang ke sini besok."}]},{"pattern":"～ても (〜temo)","meaning":"'Even if', 'even though', or 'although'.","meaningId":"'Sekalipun', 'meskipun', atau 'meskipun'.","formation":"Verb-て form + も, い-Adjective (～く) + ても, な-Adjective/Noun (～で) + も","formationId":"Bentuk Kata Kerja-て + も, い-Kata Sifat (～く) + ても, な-Kata Sifat/Kata Benda (～で) + も","examples":[{"jp":"雨が降っても、運動会は開催されます。","romaji":"Ame ga futte mo, undoukai wa kaisai saremasu.","en":"Even if it rains, the sports festival will be held.","id":"Meski hujan, festival olah raga tetap digelar."},{"jp":"忙しくても、毎日勉強する時間を作る。","romaji":"Isogashikute mo, mainichi benkyou suru jikan o tsukuru.","en":"Even though I'm busy, I make time to study every day.","id":"Meskipun saya sibuk, saya meluangkan waktu untuk belajar setiap hari."},{"jp":"高くても、良い品質のものを買います。","romaji":"Takakute mo, yoi hinshitsu no mono o kaimasu.","en":"Even if it's expensive, I'll buy something of good quality.","id":"Walaupun mahal, saya akan membeli yang berkualitas baik."},{"jp":"彼女が有名人でも、私は彼女のことを知らない。","romaji":"Kanojo ga yuumeijin demo, watashi wa kanojo no koto o shiranai.","en":"Even if she's famous, I don't know her.","id":"Meskipun dia terkenal, aku tidak mengenalnya."}]},{"pattern":"～といいなあ (〜to ii naa)","meaning":"Express a wish or hope; 'it would be nice if', 'I hope that'.","meaningId":"Ekspresikan keinginan atau harapan; 'alangkah baiknya jika', 'Saya harap itu'.","formation":"Verb-casual + といいなあ, い-Adjective + といいなあ, な-Adjective + だといいなあ, Noun + だといいなあ","formationId":"Kata Kerja-kasual + といいなあ, い-Kata Sifat + といいなあ, な-Kata Sifat + だといいなあ, Kata Benda + だといいなあ","examples":[{"jp":"明日晴れるといいなあ。","romaji":"Ashita hareru to ii naa.","en":"I hope it's sunny tomorrow.","id":"Kuharap besok cerah."},{"jp":"この試験に合格するといいなあ。","romaji":"Kono shiken ni goukaku suru to ii naa.","en":"I hope I pass this exam.","id":"Saya harap saya lulus ujian ini."},{"jp":"彼女が元気だといいなあ。","romaji":"Kanojo ga genki da to ii naa.","en":"I hope she is doing well.","id":"Saya harap dia baik-baik saja."},{"jp":"彼が新しい仕事が見つかるといいなあ。","romaji":"Kare ga atarashii shigoto ga mitsukaru to ii naa.","en":"I hope he finds a new job.","id":"Saya berharap dia mendapatkan pekerjaan baru."}]},{"pattern":"～という (〜to iu)","meaning":"Used for quoting, defining, or giving an example; 'called', 'that is to say', 'like'.","meaningId":"Digunakan untuk mengutip, mendefinisikan, atau memberi contoh; 'dipanggil', 'artinya', 'seperti'.","formation":"Noun + という + Noun, Verb-casual + という + Noun, い-Adjective + という + Noun, な-Adjective + という + Noun","formationId":"Kata Benda + という + Kata Benda, Kata Kerja Santai + という + Kata Benda, い-Kata Sifat + という + Kata Benda, な-Kata Sifat + という + Kata Benda","examples":[{"jp":"本屋で「ハリー・ポッター」という本を買いました。","romaji":"Hon'ya de 'Harry Potter' to iu hon o kaimashita.","en":"I bought a book called 'Harry Potter' at the bookstore.","id":"Saya membeli buku berjudul 'Harry Potter' di toko buku."},{"jp":"昨日、美味しいというケーキを食べました。","romaji":"Kinou, oishii to iu keeki o tabemashita.","en":"Yesterday, I ate a cake that is said to be delicious.","id":"Kemarin saya makan kue yang katanya enak."},{"jp":"彼はとても親切だという評判です。","romaji":"Kare wa totemo shinsetsu da to iu hyouban desu.","en":"He has a reputation for being very kind.","id":"Dia memiliki reputasi sebagai orang yang sangat baik hati."},{"jp":"今年の夏、東京にある「ディズニーランド」というテーマパークに行きたいです。","romaji":"Kotoshi no natsu, Toukyou ni aru 'Disneyland' to iu teema paaku ni ikitai desu.","en":"I want to go to a theme park called 'Disneyland' in Tokyo this summer.","id":"Saya ingin pergi ke taman hiburan bernama 'Disneyland' di Tokyo musim panas ini."}]},{"pattern":"～ということだ (〜to iu koto da)","meaning":"Express a conclusion or hearsay; 'I heard', 'it means', 'it can be said'.","meaningId":"Menyatakan kesimpulan atau desas-desus; 'Saya dengar', 'artinya', 'bisa dikatakan'.","formation":"Verb-casual + ということだ, い-Adjective + ということだ, な-Adjective + だということだ, Noun + だということだ","formationId":"Kata Kerja-kasual + ということだ, い-Kata Sifat + ということだ, な-Kata Sifat + だということだ, Kata Benda + だということだ","examples":[{"jp":"彼は来週結婚するということだ。","romaji":"Kare wa raishuu kekkon suru to iu koto da.","en":"I heard that he is getting married next week.","id":"Kudengar dia akan menikah minggu depan."},{"jp":"この試験は難しいということだ。","romaji":"Kono shiken wa muzukashii to iu koto da.","en":"It means this exam is difficult.","id":"Artinya ujian ini sulit."},{"jp":"彼女が引っ越したということだ。","romaji":"Kanojo ga hikkoshita to iu koto da.","en":"I heard that she has moved.","id":"Saya mendengar bahwa dia telah pindah."},{"jp":"彼は仕事がうまくいかないだということだ。","romaji":"Kare wa shigoto ga umaku ikanai da to iu koto da.","en":"It can be said that his work is not going well.","id":"Bisa dikatakan pekerjaannya kurang berjalan dengan baik."}]},{"pattern":"～というと (〜to iu to)","meaning":"Used to provide an example or characteristic related to the topic; 'when it comes to', 'speaking of'.","meaningId":"Digunakan untuk memberikan contoh atau ciri-ciri yang berkaitan dengan topik; 'bila menyangkut', 'berbicara tentang'.","formation":"Noun + というと","formationId":"Kata benda + というと","examples":[{"jp":"日本料理というと、寿司が思い浮かぶ。","romaji":"Nihon ryouri to iu to, sushi ga omoiukabu.","en":"When it comes to Japanese cuisine, sushi comes to mind.","id":"Ketika berbicara tentang masakan Jepang, sushi pasti terlintas di benak Anda."},{"jp":"パリというと、エッフェル塔を思い出す。","romaji":"Pari to iu to, Efferu Tou wo omoidasu.","en":"Speaking of Paris, I recall the Eiffel Tower.","id":"Berbicara tentang Paris, saya ingat Menara Eiffel."},{"jp":"夏休みというと、海に行くことが楽しみだ。","romaji":"Natsu yasumi to iu to, umi ni iku koto ga tanoshimi da.","en":"When it comes to summer vacation, I look forward to going to the beach.","id":"Ketika tiba liburan musim panas, saya menantikan untuk pergi ke pantai."},{"jp":"彼というと、いつも元気な人だと思う。","romaji":"Kare to iu to, itsumo genki na hito da to omou.","en":"Speaking of him, I think he's always energetic.","id":"Ngomong-ngomong tentang dia, menurutku dia selalu energik."}]},{"pattern":"～というの～ (〜to iu no〜)","meaning":"Explain or emphasize the reason for a situation or action.","meaningId":"Menjelaskan atau menekankan alasan suatu situasi atau tindakan.","formation":"Verb-casual + というの, い-Adjective + というの, な-Adjective + だというの, Noun + だというの","formationId":"Kata Kerja-kasual + というの, い-Kata Sifat + というの, な-Kata Sifat + だというの, Kata Benda + だというの","examples":[{"jp":"遅刻したのは、電車が遅れたというのだ。","romaji":"Chikoku shita no wa, densha ga okureta to iu no da.","en":"The reason I was late is because the train was delayed.","id":"Alasan saya terlambat adalah karena keretanya tertunda."},{"jp":"この部屋が汚いのは、掃除をしなかったというのだ。","romaji":"Kono heya ga kitanai no wa, souji o shinakatta to iu no da.","en":"The reason this room is dirty is because I didn't clean it.","id":"Alasan mengapa ruangan ini kotor adalah karena saya tidak membersihkannya."},{"jp":"彼女が怒っているのは、彼が約束を破ったというのだ。","romaji":"Kanojo ga okotte iru no wa, kare ga yakusoku o yabutta to iu no da.","en":"The reason she is angry is that he broke his promise.","id":"Alasan dia marah adalah karena dia melanggar janjinya."},{"jp":"彼が成功したのは、努力して勉強したというのだ。","romaji":"Kare ga seikou shita no wa, doryoku shite benkyou shita to iu no da.","en":"The reason he succeeded is because he studied hard.","id":"Alasan dia berhasil adalah karena dia belajar dengan giat."}]},{"pattern":"～というのは (〜to iu no wa)","meaning":"Used to provide an explanation or definition; 'that is to say...', 'by that, I mean...'.","meaningId":"Digunakan untuk memberikan penjelasan atau definisi; 'artinya...', 'maksudku...'.","formation":"Phrase/sentence + というのは + explanation/definition","formationId":"Frasa/kalimat + というのは + penjelasan/definisi","examples":[{"jp":"日本に行くというのは、日本に旅行することです。","romaji":"Nihon ni iku to iu no wa, Nihon ni ryokou suru koto desu.","en":"Going to Japan, that is to say, traveling to Japan.","id":"Pergi ke Jepang, artinya bepergian ke Jepang."},{"jp":"この問題は難しいというのは、解決に時間がかかるということです。","romaji":"Kono mondai wa muzukashii to iu no wa, kaiketsu ni jikan ga kakaru to iu koto desu.","en":"When I say this problem is difficult, I mean it takes time to solve.","id":"Ketika saya mengatakan masalah ini sulit, maksud saya perlu waktu untuk menyelesaikannya."},{"jp":"彼が怒っているというのは、彼が不満を感じているということです。","romaji":"Kare ga okotteiru to iu no wa, kare ga fuman wo kanjiteiru to iu koto desu.","en":"By saying that he's angry, I mean he's feeling dissatisfied.","id":"Dengan mengatakan bahwa dia marah, maksudku dia merasa tidak puas."},{"jp":"太るというのは、体重が増えるということです。","romaji":"Futoru to iu no wa, taijuu ga fueru to iu koto desu.","en":"Gaining weight, that is to say, increasing one's body weight.","id":"Menambah berat badan, maksudnya menambah berat badan seseorang."}]},{"pattern":"～というより (〜to iu yori)","meaning":"Express a comparison with preference; 'rather than', 'more like', 'instead of'.","meaningId":"Nyatakan perbandingan dengan preferensi; 'daripada', 'lebih seperti', 'daripada'.","formation":"Verb-casual + というより, い-Adjective + というより, な-Adjective + だというより, Noun + だというより","formationId":"Kata Kerja-kasual + というより, い-Kata Sifat + というより, な-Kata Sifat + だというより, Kata Benda + だというより","examples":[{"jp":"この部屋は狭いというより、居心地がいい。","romaji":"Kono heya wa semai to iu yori, igokochi ga ii.","en":"Rather than saying this room is small, it's more like it's cozy.","id":"Daripada mengatakan ruangan ini kecil, ini lebih seperti nyaman."},{"jp":"彼は怖いというより、頼りがいがある。","romaji":"Kare wa kowai to iu yori, tayori gai ga aru.","en":"Instead of saying he's scary, he's more like a reliable person.","id":"Daripada bilang dia menakutkan, dia lebih seperti orang yang bisa diandalkan."},{"jp":"映画はつまらないというより、ちょっと長かった。","romaji":"Eiga wa tsumaranai to iu yori, chotto nagakatta.","en":"Rather than calling the movie boring, I'd say it was a bit long.","id":"Daripada menyebut filmnya membosankan, menurutku itu agak panjang."},{"jp":"彼女は友達だというより、家族のような存在だ。","romaji":"Kanojo wa tomodachi da to iu yori, kazoku no you na sonzai da.","en":"Rather than a friend, she's more like family.","id":"Daripada seorang teman, dia lebih seperti keluarga."}]},{"pattern":"～といっても (〜to ittemo)","meaning":"Express the meaning 'even though', 'although', 'but'.","meaningId":"Mengungkapkan arti 'walaupun', 'walaupun', 'tetapi'.","formation":"Verb-casual + といっても, い-Adjective + といっても, な-Adjective + だといっても, Noun + だといっても","formationId":"Kata Kerja-kasual + といっても, い-Kata Sifat + といっても, な-Kata Sifat + だといっても, Kata Benda + だといっても","examples":[{"jp":"彼は有名だといっても、みんなに知られているわけではありません。","romaji":"Kare wa yuumei da to ittemo, minna ni shirarete iru wake de wa arimasen.","en":"Even though he's famous, it doesn't mean everyone knows him.","id":"Meski terkenal, bukan berarti semua orang mengenalnya."},{"jp":"このスープは辛いといっても、私にはちょうどいいです。","romaji":"Kono suupu wa karai to ittemo, watashi ni wa choudo ii desu.","en":"Although this soup is spicy, it's just right for me.","id":"Meski sup ini pedas, tapi pas untukku."},{"jp":"彼女は若いですが、経験があるといっても、まだ新人です。","romaji":"Kanojo wa wakai desu ga, keiken ga aru to ittemo, mada shinjin desu.","en":"She's young, and although she has some experience, she's still a newcomer.","id":"Dia masih muda, dan meskipun dia memiliki pengalaman, dia masih pendatang baru."},{"jp":"このレストランは高いだといっても、美味しい料理が食べられるので価値があります。","romaji":"Kono resutoran wa takai da to ittemo, oishii ryouri ga taberareru node kachi ga arimasu.","en":"Even though this restaurant is expensive, it's worth it because you can enjoy delicious dishes.","id":"Meski restoran ini mahal, namun worth it karena Anda bisa menikmati hidangan lezat."}]},{"pattern":"～とおり (〜toori)","meaning":"Expresses that something is done 'as is', 'as stated', or 'as instructed'.","meaningId":"Menyatakan bahwa sesuatu dilakukan 'sebagaimana adanya', 'sebagaimana dinyatakan', atau 'sesuai instruksi'.","formation":"Verb-て form + とおり, Noun + のとおり","formationId":"Bentuk kata kerja-て + とおり, Kata Benda + のとおり","examples":[{"jp":"先生が言ったとおり、宿題をやりました。","romaji":"Sensei ga itta toori, shukudai wo yarimashita.","en":"I did my homework exactly as the teacher said.","id":"Saya mengerjakan pekerjaan rumah saya persis seperti yang diperintahkan guru."},{"jp":"地図に書いてあるとおりに行けば、駅に着きます。","romaji":"Chizu ni kaite aru toori ni ikeba, eki ni tsukimasu.","en":"If you follow what's written on the map, you'll arrive at the station.","id":"Jika Anda mengikuti apa yang tertulis di peta, Anda akan tiba di stasiun."},{"jp":"レシピのとおりにケーキを作った。","romaji":"Reshipi no toori ni keeki o tsukutta.","en":"I baked the cake according to the recipe.","id":"Saya memanggang kuenya sesuai resep."},{"jp":"彼女は約束したとおりに時間通りに来ました。","romaji":"Kanojo wa yakusoku shita toori ni jikan doori ni kimashita.","en":"She arrived on time, just as she promised.","id":"Dia tiba tepat waktu, seperti yang dia janjikan."}]},{"pattern":"～とく (〜toku)","meaning":"Express doing something in advance or for future convenience (casual form of ～ておく).","meaningId":"Ekspresikan melakukan sesuatu terlebih dahulu atau untuk kenyamanan di masa depan (bentuk biasa dari ～ておく).","formation":"Verb-て form + とく (e.g., 食べておく→食べとく, 読んでおく→読んどく)","formationId":"Bentuk kata kerja-て + とく (misalnya, 食べておく→食べとく, 読んでおく→読んどく)","examples":[{"jp":"夜遅くなるから、今晩のご飯を作っとく。","romaji":"Yoru osoku naru kara, konban no gohan wo tsukutoku.","en":"Since it will be late tonight, I'll prepare dinner in advance.","id":"Karena malam ini akan larut, aku akan menyiapkan makan malam terlebih dahulu."},{"jp":"傘が必要かもしれないので、持っておく。","romaji":"Kasa ga hitsuyou kamoshirenai node, motte oku.","en":"I might need an umbrella, so I'll bring one along (just in case).","id":"Saya mungkin memerlukan payung, jadi saya akan membawanya (untuk berjaga-jaga)."},{"jp":"試験が近いから、今から勉強しとこう。","romaji":"Shiken ga chikai kara, ima kara benkyou shitokou.","en":"The exam is coming up, so I'll start studying now.","id":"Ujiannya sebentar lagi, jadi aku akan mulai belajar sekarang."},{"jp":"明日は忙しいので、洗濯をしとく。","romaji":"Ashita wa isogashii node, sentaku wo shitoku.","en":"Since I'll be busy tomorrow, I'll do the laundry in advance.","id":"Karena saya akan sibuk besok, saya akan mencuci pakaian terlebih dahulu."}]},{"pattern":"～ところが (〜tokoro ga)","meaning":"Expresses a contrast or unexpected outcome; 'however', 'but', 'even though'.","meaningId":"Mengekspresikan hasil yang kontras atau tidak terduga; 'namun', 'tetapi', 'meskipun'.","formation":"Phrase 1 (expected situation) + ところが + Phrase 2 (unexpected result)","formationId":"Frase 1 (situasi yang diharapkan) + ところが + Frase 2 (hasil yang tidak terduga)","examples":[{"jp":"彼はいつも遅刻するところが、今日は早く来ました。","romaji":"Kare wa itsumo chikoku suru tokoro ga, kyou wa hayaku kimashita.","en":"He's always late, but today he arrived early.","id":"Dia selalu terlambat, tapi hari ini dia datang lebih awal."},{"jp":"昨日は暑かったところが、今日は寒くなりました。","romaji":"Kinou wa atsukatta tokoro ga, kyou wa samuku narimashita.","en":"Yesterday was hot, but today it got cold.","id":"Kemarin panas, tapi hari ini dingin."},{"jp":"試合で負けると思ったところが、意外にも勝ちました。","romaji":"Shiai de makeru to omotta tokoro ga, igai ni mo kachimashita.","en":"I thought we would lose the match, but surprisingly we won.","id":"Saya pikir kami akan kalah, tapi secara mengejutkan kami menang."},{"jp":"決勝戦で優勝するところが、最後のポイントで負けました。","romaji":"Kesshousen de yuushou suru tokoro ga, saigo no pointo de makemashita.","en":"We were about to win the final, but we lost at the last point.","id":"Kami hampir memenangkan final, tapi kami kalah di poin terakhir."}]},{"pattern":"～ところだった (〜tokoro datta)","meaning":"Expresses a near miss or a situation that almost happened; 'was just about to', 'almost', 'nearly'.","meaningId":"Mengekspresikan kejadian nyaris celaka atau situasi yang hampir terjadi; 'baru saja akan', 'hampir', 'hampir'.","formation":"Verb (dictionary form or ている form) + ところだった","formationId":"Kata kerja (bentuk kamus atau bentuk ている) + ところだった","examples":[{"jp":"もう少しで遅れるところだった。","romaji":"Mou sukoshi de okureru tokoro datta.","en":"I was just about to be late.","id":"Aku baru saja akan terlambat."},{"jp":"彼が危うく事故にあうところだった。","romaji":"Kare ga ayauku jiko ni au tokoro datta.","en":"He almost had an accident.","id":"Dia hampir mengalami kecelakaan."},{"jp":"電車に乗るところだったが、ドアが閉まってしまった。","romaji":"Densha ni noru tokoro datta ga, doa ga shimatte shimatta.","en":"I was just about to get on the train, but the door closed.","id":"Saya baru saja hendak naik kereta, tetapi pintunya tertutup."},{"jp":"忘れ物をするところだった。","romaji":"Wasuremono wo suru tokoro datta.","en":"I almost forgot my belongings.","id":"Aku hampir melupakan barang-barangku."}]},{"pattern":"ところで","meaning":"Used for changing the topic or bringing up a new topic; 'by the way', 'speaking of'.","meaningId":"Digunakan untuk mengganti topik atau mengangkat topik baru; 'ngomong-ngomong', 'berbicara tentang'.","formation":"ところで + new topic or question","formationId":"ところで + topik atau pertanyaan baru","examples":[{"jp":"ところで、昨日の宿題はもう終わりましたか？","romaji":"Tokorode, kinou no shukudai wa mou owari mashita ka?","en":"By the way, did you finish yesterday's homework?","id":"Ngomong-ngomong, apakah kamu sudah menyelesaikan pekerjaan rumah kemarin?"},{"jp":"彼はプールで泳いでいます。ところで、お昼ご飯は何にしますか？","romaji":"Kare wa puuru de oyoide imasu. Tokorode, ohiru gohan wa nani ni shimasu ka?","en":"He is swimming in the pool. By the way, what do you want for lunch?","id":"Dia sedang berenang di kolam. Ngomong-ngomong, kamu mau makan siang apa?"},{"jp":"昨日は楽しかったですね。ところで、この写真を見ましたか？","romaji":"Kinou wa tanoshikatta desu ne. Tokorode, kono shashin wo mimashita ka?","en":"Yesterday was fun, wasn't it? By the way, did you see this photo?","id":"Kemarin menyenangkan, bukan? Ngomong-ngomong, apakah kamu melihat foto ini?"},{"jp":"ところで、明日の会議の時間を知っていますか？","romaji":"Tokorode, ashita no kaigi no jikan wo shitte imasu ka?","en":"By the way, do you know the time of tomorrow's meeting?","id":"Ngomong-ngomong, apa kamu tahu waktu pertemuan besok?"}]},{"pattern":"～としたら (〜to shitara)","meaning":"Express a hypothetical situation; 'if', 'suppose', 'assuming'.","meaningId":"Ekspresikan situasi hipotetis; 'jika', 'seandainya', 'dengan asumsi'.","formation":"Verb-casual + としたら, い-Adjective + としたら, な-Adjective + だとしたら, Noun + だとしたら","formationId":"Kata Kerja-kasual + としたら, い-Kata Sifat + としたら, な-Kata Sifat + だとしたら, Kata Benda + だとしたら","examples":[{"jp":"明日雨が降るとしたら、傘を持って行きましょう。","romaji":"Ashita ame ga furu to shitara, kasa wo motte ikimashou.","en":"If it rains tomorrow, let's bring an umbrella.","id":"Kalau besok hujan, yuk bawa payung."},{"jp":"このケーキが美味しくないとしたら、誰も食べないでしょう。","romaji":"Kono keeki ga oishikunai to shitara, daremo tabenai deshou.","en":"If this cake is not delicious, nobody will eat it.","id":"Jika kue ini tidak enak, tidak ada yang akan memakannya."},{"jp":"彼が病気だとしたら、すぐに病院に行かせてあげてください。","romaji":"Kare ga byouki da to shitara, sugu ni byouin ni ikasete agete kudasai.","en":"If he is sick, please take him to the hospital right away.","id":"Jika dia sakit, harap segera membawanya ke rumah sakit."},{"jp":"彼女が学生だとしたら、このレストランは割引があるでしょう。","romaji":"Kanojo ga gakusei da to shitara, kono resutoran wa waribiki ga aru deshou.","en":"If she is a student, there will be a discount at this restaurant.","id":"Jika dia seorang pelajar, akan ada diskon di restoran ini."}]},{"pattern":"～として (〜to shite)","meaning":"Indicates a role, capacity, or identity; 'as', 'in the capacity of'.","meaningId":"Menunjukkan peran, kapasitas, atau identitas; 'sebagai', 'dalam kapasitas'.","formation":"Verb-casual + として, い-Adjective + として, な-Adjective + だとして, Noun + だとして","formationId":"Kata Kerja-kasual + として, い-Kata Sifat + として, な-Kata Sifat + だとして, Kata Benda + だとして","examples":[{"jp":"彼は弁護士として働いています。","romaji":"Kare wa bengoshi to shite hataraite imasu.","en":"He is working as a lawyer.","id":"Dia bekerja sebagai pengacara."},{"jp":"この料理はスナックとして食べられます。","romaji":"Kono ryouri wa sunakku to shite taberaremasu.","en":"This dish can be eaten as a snack.","id":"Hidangan ini bisa disantap sebagai camilan."},{"jp":"彼女はリーダーとして尊敬されている。","romaji":"Kanojo wa riidaa to shite sonkei sarete iru.","en":"She is respected as a leader.","id":"Dia dihormati sebagai seorang pemimpin."},{"jp":"この本は参考書として使われます。","romaji":"Kono hon wa sankousho to shite tsukawaremasu.","en":"This book is used as a reference.","id":"Buku ini digunakan sebagai referensi."}]},{"pattern":"～どんなに～ことか (〜donna ni〜koto ka)","meaning":"Expresses the extent of something or emphasizes the degree of a condition or situation.","meaningId":"Mengekspresikan luasnya sesuatu atau menekankan derajat suatu kondisi atau situasi.","formation":"どんなに + Adjective + ことか, どんなに + Verb + ことか","formationId":"どんなに + Kata Sifat + ことか, どんなに + Kata Kerja + ことか","examples":[{"jp":"どんなに疲れたことか、言葉では表せません。","romaji":"Donna ni tsukareta koto ka, kotoba de wa arawasemasen.","en":"I can't put into words how tired I am.","id":"Saya tidak bisa mengungkapkan dengan kata-kata betapa lelahnya saya."},{"jp":"どんなに辛いことか、彼女は毎日頑張って働いています。","romaji":"Donna ni tsurai koto ka, kanojo wa mainichi ganbatte hataraiteimasu.","en":"How hard it must be, she works hard every day.","id":"Betapa sulitnya, dia bekerja keras setiap hari."},{"jp":"彼の成功はどんなに喜ばしいことか。","romaji":"Kare no seikou wa donna ni yorokobashii koto ka.","en":"How happy his success must be.","id":"Betapa bahagianya kesuksesannya."},{"jp":"どんなに楽しいことか、みんなで旅行に行く。","romaji":"Donna ni tanoshii koto ka, minna de ryokou ni iku.","en":"How fun it is to go on a trip with everyone.","id":"Betapa menyenangkannya melakukan perjalanan bersama semua orang."}]},{"pattern":"どんなに～ても","meaning":"Expresses 'no matter how much' or 'even if'; emphasizes the degree of a situation.","meaningId":"Menyatakan 'tidak peduli berapa banyak' atau 'sekalipun'; menekankan derajat suatu situasi.","formation":"どんなに + Verb-てform + も, どんなに + い-Adjective-てform + も, どんなに + な-Adjective + でも","formationId":"どんなに + Kata Kerja-てform + も, どんなに + い-Kata Sifat-てform + も, どんなに + な-Kata Sifat + でも","examples":[{"jp":"どんなに勉強しても、まだわからないことがある。","romaji":"Donna ni benkyou shite mo, mada wakaranai koto ga aru.","en":"No matter how much I study, there are still things I don't understand.","id":"Tidak peduli seberapa banyak aku belajar, masih ada hal-hal yang aku tidak mengerti."},{"jp":"どんなに速く走っても、彼には勝てません。","romaji":"Donna ni hayaku hashitte mo, kare ni wa katemasen.","en":"No matter how fast I run, I can't beat him.","id":"Tidak peduli seberapa cepat aku berlari, aku tidak bisa mengalahkannya."},{"jp":"どんなに疲れても、仕事を終わらせるまで帰れません。","romaji":"Donna ni tsukarete mo, shigoto o owaraseru made kaeremasen.","en":"No matter how tired I am, I can't go home until I finish my work.","id":"Betapapun lelahnya aku, aku tidak bisa pulang sampai aku menyelesaikan pekerjaanku."},{"jp":"どんなに美味しくても、これ以上食べられない。","romaji":"Donna ni oishikute mo, kore ijou taberarenai.","en":"No matter how delicious it is, I can't eat any more.","id":"Betapapun enaknya, saya tidak bisa makan lagi."}]},{"pattern":"～ないことはない (〜nai koto wa nai)","meaning":"Express the idea that 'it's not that it's impossible' or 'it's not that it cannot be done'.","meaningId":"Ekspresikan gagasan bahwa 'bukannya tidak mungkin' atau 'bukannya tidak bisa dilakukan'.","formation":"Verb-ない form + ことはない","formationId":"Bentuk kata kerja-ない + ことはない","examples":[{"jp":"この問題を解けないことはないが、時間がかかりそうだ。","romaji":"Kono mondai wo tokenai koto wa nai ga, jikan ga kakari sou da.","en":"It's not that I can't solve this problem, but it seems like it will take time.","id":"Bukannya saya tidak bisa menyelesaikan masalah ini, tapi sepertinya butuh waktu."},{"jp":"彼に会わないことはないけど、あまり話したくない。","romaji":"Kare ni awanai koto wa nai kedo, amari hanashitakunai.","en":"It's not that I can't meet him, but I don't really want to talk.","id":"Bukannya aku tidak bisa bertemu dengannya, tapi aku sedang tidak ingin bicara."},{"jp":"この映画を見ないことはないけれど、他の映画がもっと面白いと思う。","romaji":"Kono eiga wo minai koto wa nai keredo, hoka no eiga ga motto omoshiroi to omou.","en":"It's not that I cannot watch this movie, but I think other movies are more interesting.","id":"Bukannya saya tidak bisa menonton film ini, tapi menurut saya film lain lebih menarik."},{"jp":"その本を読まないことはないが、長いので気をつけてください。","romaji":"Sono hon wo yomanai koto wa nai ga, nagai node ki wo tsukete kudasai.","en":"It's not that I can't read that book, but it's long, so be careful.","id":"Bukannya saya tidak bisa membaca buku itu, tapi bukunya panjang, jadi berhati-hatilah."}]},{"pattern":"～ないと (〜nai to)","meaning":"Express a condition; 'if... not', 'unless', 'must'.","meaningId":"Nyatakan suatu kondisi; 'jika... tidak', 'kecuali', 'harus'.","formation":"Verb-negative form + ないと","formationId":"Bentuk kata kerja negatif + ないと","examples":[{"jp":"朝食を食べないと、お腹が空く。","romaji":"Asa gohan wo tabenai to, onaka ga suku.","en":"If I don't eat breakfast, I will be hungry.","id":"Jika saya tidak sarapan, saya akan lapar."},{"jp":"宿題をしないと、先生に怒られる。","romaji":"Shukudai wo shinai to, sensei ni okorareru.","en":"If I don't do my homework, the teacher will be angry.","id":"Jika saya tidak mengerjakan pekerjaan rumah saya, guru akan marah."},{"jp":"充電をしないと、電話が使えなくなる。","romaji":"Juden wo shinai to, denwa ga tsukaenaku naru.","en":"If I don't charge it, I won't be able to use the phone.","id":"Jika saya tidak mengisi dayanya, saya tidak akan dapat menggunakan telepon."},{"jp":"この事故を報告しないと、問題が大きくなる。","romaji":"Kono jiko wo houkoku shinai to, mondai ga ookiku naru.","en":"If I don't report this accident, the problem will become bigger.","id":"Jika saya tidak melaporkan kecelakaan ini, masalahnya akan semakin besar."}]},{"pattern":"～なぜなら (〜nazenara)","meaning":"Express a reason or explanation; 'because', 'the reason is'.","meaningId":"Nyatakan alasan atau penjelasan; 'karena', 'alasannya adalah'.","formation":"Sentence/Statement + なぜなら + Reason + から/だから","formationId":"Kalimat/Pernyataan + なぜなら + Alasan + から/だから","examples":[{"jp":"このレストランが大好きだ。なぜなら料理が美味しいから。","romaji":"Kono resutoran ga daisuki da. Nazenara ryouri ga oishii kara.","en":"I love this restaurant because the food is delicious.","id":"Saya suka restoran ini karena makanannya enak."},{"jp":"彼女は試験に合格しなかった。なぜなら勉強しなかったから。","romaji":"Kanojo wa shiken ni goukaku shinakatta. Nazenara benkyou shinakatta kara.","en":"She didn't pass the exam because she didn't study.","id":"Dia tidak lulus ujian karena dia tidak belajar."},{"jp":"私は映画を見に行かない。なぜなら今日は忙しいから。","romaji":"Watashi wa eiga o mi ni ikanai. Nazenara kyou wa isogashii kara.","en":"I won't go to see a movie because I am busy today.","id":"Saya tidak akan pergi menonton film karena saya sibuk hari ini."},{"jp":"彼はこのプロジェクトを任せられる。なぜなら経験が豊富だから。","romaji":"Kare wa kono purojekuto wo makaserareru. Nazenara keiken ga houfu dakara.","en":"He can be trusted with this project because he has a wealth of experience.","id":"Ia dapat dipercaya mengerjakan proyek ini karena memiliki segudang pengalaman."}]},{"pattern":"～など (〜nado)","meaning":"Indicates a non-exhaustive list of examples; 'such as', 'things like', 'among others'.","meaningId":"Menunjukkan daftar contoh yang tidak lengkap; 'seperti', 'hal-hal seperti', 'antara lain'.","formation":"Noun + など","formationId":"Kata benda + など","examples":[{"jp":"魚、果物などを市場で買いました。","romaji":"Sakana, kudamono nado wo ichiba de kaimashita.","en":"I bought fish, fruits, and such at the market.","id":"Saya membeli ikan, buah-buahan, dan sejenisnya di pasar."},{"jp":"彼は日本語、英語、中国語などを話せます。","romaji":"Kare wa nihongo, eigo, chuugokugo nado wo hanasemasu.","en":"He can speak languages such as Japanese, English, and Chinese.","id":"Dia dapat berbicara bahasa seperti Jepang, Inggris, dan Cina."},{"jp":"美術館では絵画、彫刻などの作品を見ました。","romaji":"Bijutsukan de wa kaiga, choukoku nado no sakuhin wo mimashita.","en":"At the art museum, I saw works like paintings, sculptures, and others.","id":"Di museum seni, saya melihat karya-karya seperti lukisan, patung, dan lain-lain."},{"jp":"この店ではパン、ケーキなどのお菓子を売っています。","romaji":"Kono mise de wa pan, keeki nado no okashi wo utteimasu.","en":"This store sells sweets such as bread, cakes, and so on.","id":"Toko ini menjual manisan seperti roti, kue, dan lain sebagainya."}]},{"pattern":"～なんか (〜nanka)","meaning":"Expresses the idea of 'things like' or 'something like', used for listing examples or downplaying something.","meaningId":"Mengekspresikan gagasan 'hal-hal seperti' atau 'sesuatu seperti', digunakan untuk membuat daftar contoh atau meremehkan sesuatu.","formation":"Noun + なんか, Verb-casual + なんか, い-Adjective + なんか, な-Adjective + なんか","formationId":"Kata benda + なんか, Kata Kerja-kasual + なんか, い-Kata Sifat + なんか, な-Kata Sifat + なんか","examples":[{"jp":"お金なんかいらない。","romaji":"Okane nanka iranai.","en":"I don't need money or anything like that.","id":"Saya tidak butuh uang atau semacamnya."},{"jp":"彼はピアノなんかも弾けます。","romaji":"Kare wa piano nanka mo hikemasu.","en":"He can play things like the piano.","id":"Dia bisa memainkan hal-hal seperti piano."},{"jp":"忙しいなんかじゃないよ。","romaji":"Isogashii nanka janai yo.","en":"I'm not really busy or anything like that.","id":"Aku tidak terlalu sibuk atau semacamnya."},{"jp":"彼女は親切なんかじゃない。","romaji":"Kanojo wa shinsetsu nanka janai.","en":"She's not kind or anything like that.","id":"Dia tidak baik atau semacamnya."}]},{"pattern":"～において (〜ni oite)","meaning":"Indicates the place, time, or context where an action or situation takes place.","meaningId":"Menunjukkan tempat, waktu, atau konteks di mana suatu tindakan atau situasi terjadi.","formation":"Noun (Place/Time/Context) + において","formationId":"Kata Benda (Tempat/Waktu/Konteks) + において","examples":[{"jp":"日本において、お盆は家族が集まる大切な行事です。","romaji":"Nihon ni oite, obon wa kazoku ga atsumaru taisetsu na gyouji desu.","en":"In Japan, Obon is an important event where families gather.","id":"Di Jepang, Obon merupakan acara penting tempat berkumpulnya keluarga."},{"jp":"会議において、彼の意見が一番説得力がありました。","romaji":"Kaigi ni oite, kare no iken ga ichiban settokuryoku ga arimashita.","en":"In the meeting, his opinion was the most persuasive.","id":"Dalam pertemuan tersebut, pendapatnya paling persuasif."},{"jp":"科学の分野において、研究が日々進んでいます。","romaji":"Kagaku no bun'ya ni oite, kenkyuu ga hibi susunde imasu.","en":"In the field of science, research is advancing daily.","id":"Di bidang sains, penelitian semakin maju setiap harinya."},{"jp":"幼少期において、子供たちは勢いよく物を覚えます。","romaji":"Youshouki ni oite, kodomo-tachi wa ikioi yoku mono wo oboemasu.","en":"During early childhood, children learn things rapidly.","id":"Pada masa anak usia dini, anak-anak belajar berbagai hal dengan cepat."}]},{"pattern":"～にかわって (〜ni kawatte)","meaning":"Expresses 'in place of', 'on behalf of', or 'instead of'.","meaningId":"Menyatakan 'sebagai pengganti', 'atas nama', atau 'sebagai ganti'.","formation":"Noun + にかわって","formationId":"Kata benda + にかわって","examples":[{"jp":"彼が病気なので、私が会議に出席することになりました。私が彼にかわって会議に出席します。","romaji":"Kare ga byouki na no de, watashi ga kaigi ni shusseki suru koto ni narimashita. Watashi ga kare ni kawatte kaigi ni shusseki shimasu.","en":"He is sick, so I will attend the meeting. I will attend the meeting on his behalf.","id":"Dia sakit, jadi saya akan menghadiri pertemuan itu. Saya akan menghadiri pertemuan atas namanya."},{"jp":"母は忙しいので、私が母にかわって料理を作ります。","romaji":"Haha wa isogashii no de, watashi ga haha ni kawatte ryouri wo tsukurimasu.","en":"My mother is busy, so I will cook the meal instead of her.","id":"Ibuku sedang sibuk, jadi aku yang akan memasak makanannya, bukan dia."},{"jp":"今度の旅行は妹にかわって、私が一緒に行きます。","romaji":"Kondo no ryokou wa imouto ni kawatte, watashi ga issho ni ikimasu.","en":"For this trip, I will go together instead of my younger sister.","id":"Untuk perjalanan kali ini, aku akan pergi bersama, bukannya adik perempuanku."},{"jp":"先生が出張中でいないので、助手が先生にかわってクラスを担当します。","romaji":"Sensei ga shucchou chuu de inai no de, joshu ga sensei ni kawatte kurasu wo tantou shimasu.","en":"The teacher is not here because of a business trip, so the assistant will take charge of the class instead of the teacher.","id":"Guru tidak ada di sini karena perjalanan bisnis, jadi asisten akan bertanggung jawab atas kelas, bukan guru."}]},{"pattern":"～にしては (〜ni shite wa)","meaning":"Express 'for' or 'considering' in the sense of being unusual or unexpected.","meaningId":"Ekspresikan 'untuk' atau 'mempertimbangkan' dalam arti tidak biasa atau tidak terduga.","formation":"Verb-casual + にしては, い-Adjective + にしては, な-Adjective + にしては, Noun + にしては","formationId":"Kata Kerja-kasual + にしては, い-Kata Sifat + にしては, な-Kata Sifat + にしては, Kata Benda + にしては","examples":[{"jp":"彼女は初心者にしては、上手に水泳ができる。","romaji":"Kanojo wa shoshinsha ni shite wa, jouzu ni suiei ga dekiru.","en":"Considering she is a beginner, she can swim well.","id":"Mengingat dia seorang pemula, dia bisa berenang dengan baik."},{"jp":"このお寿司は安いにしては、とても美味しい。","romaji":"Kono o-sushi wa yasui ni shite wa, totemo oishii.","en":"Considering this sushi is cheap, it's very delicious.","id":"Mengingat sushi ini murah, rasanya sangat enak."},{"jp":"彼は若いにしては、とても落ち着いている。","romaji":"Kare wa wakai ni shite wa, totemo ochitsuite iru.","en":"Considering he is young, he is very calm.","id":"Mengingat dia masih muda, dia sangat tenang."},{"jp":"あの人は外国人にしては、日本語がうまい。","romaji":"Ano hito wa gaikokujin ni shite wa, nihongo ga umai.","en":"For a foreigner, that person is good at Japanese.","id":"Bagi orang asing, orang itu pandai berbahasa Jepang."}]},{"pattern":"～にしても (〜ni shitemo)","meaning":"Expresses 'even if', 'no matter', 'regardless of'.","meaningId":"Menyatakan 'walaupun', 'tidak masalah', 'terlepas dari'.","formation":"Verb-casual + にしても, い-Adjective + にしても, な-Adjective + だにしても, Noun + だにしても","formationId":"Kata Kerja-kasual + にしても, い-Kata Sifat + にしても, な-Kata Sifat + だにしても, Kata Benda + だにしても","examples":[{"jp":"雨が降るにしても、学校へ行かなければなりません。","romaji":"Ame ga furu ni shitemo, gakkou e ikanakereba narimasen.","en":"Even if it rains, I have to go to school.","id":"Walaupun hujan, aku tetap harus pergi ke sekolah."},{"jp":"彼女が怒っているにしても、話し合いは避けられない。","romaji":"Kanojo ga okotte iru ni shitemo, hanashiai wa sakerarenai.","en":"Even if she is angry, we can't avoid talking.","id":"Sekalipun dia marah, kami tidak bisa menghindari pembicaraan."},{"jp":"このレストランが高いにしても、料理の質がよくておすすめです。","romaji":"Kono resutoran ga takai ni shitemo, ryouri no shitsu ga yokute osusume desu.","en":"Even if this restaurant is expensive, I recommend it because the quality of the food is good.","id":"Walaupun restoran ini mahal, saya merekomendasikannya karena kualitas makanannya bagus."},{"jp":"彼が有名だにしても、彼の私生活について話すのは失礼だ。","romaji":"Kare ga yuumei da ni shitemo, kare no shiseikatsu ni tsuite hanasu no wa shitsurei da.","en":"Even if he is famous, it's rude to talk about his private life.","id":"Sekalipun dia terkenal, tidak sopan membicarakan kehidupan pribadinya."}]},{"pattern":"～について (〜ni tsuite)","meaning":"Expressing 'about', 'concerning', or 'regarding'.","meaningId":"Mengekspresikan 'tentang', 'mengenai', atau 'mengenai'.","formation":"Noun + について","formationId":"Kata benda + について","examples":[{"jp":"日本の文化について学びたいです。","romaji":"Nihon no bunka ni tsuite manabitai desu.","en":"I want to learn about Japanese culture.","id":"Saya ingin belajar tentang budaya Jepang."},{"jp":"彼の意見について話し合いましょう。","romaji":"Kare no iken ni tsuite hanashiaimashou.","en":"Let's discuss his opinion.","id":"Mari kita bahas pendapatnya."},{"jp":"この問題について詳しく教えてください。","romaji":"Kono mondai ni tsuite kuwashiku oshiete kudasai.","en":"Please explain this issue in detail.","id":"Tolong jelaskan masalah ini secara rinci."},{"jp":"子供たちの教育について考えなければなりません。","romaji":"Kodomo-tachi no kyouiku ni tsuite kangaenakereba narimasen.","en":"We have to think about the children's education.","id":"Kita harus memikirkan pendidikan anak-anak."}]},{"pattern":"～にとって (〜ni totte)","meaning":"Express the meaning 'for', 'to', 'from the perspective of'.","meaningId":"Nyatakan arti 'untuk', 'ke', 'dari sudut pandang'.","formation":"Noun (person or thing) + にとって + Verb/Adjective/Noun","formationId":"Kata benda (orang atau benda) + にとって + Kata Kerja/Kata Sifat/Kata Benda","examples":[{"jp":"私にとって、健康は一番大切なことです。","romaji":"Watashi ni totte, kenkou wa ichiban taisetsu na koto desu.","en":"For me, health is the most important thing.","id":"Bagi saya, kesehatan adalah hal yang paling penting."},{"jp":"あの会社にとって、このプロジェクトは重要な意味があります。","romaji":"Ano kaisha ni totte, kono purojekuto wa juuyou na imi ga arimasu.","en":"For that company, this project has significant meaning.","id":"Bagi perusahaan itu, proyek ini mempunyai arti penting."},{"jp":"子供たちにとって、おもちゃは楽しいものです。","romaji":"Kodomotachi ni totte, omocha wa tanoshii mono desu.","en":"For children, toys are fun things.","id":"Bagi anak-anak, mainan adalah hal yang menyenangkan."},{"jp":"外国人にとって、日本語は難しい言語の一つです。","romaji":"Gaikokujin ni totte, nihongo wa muzukashii gengo no hitotsu desu.","en":"For foreigners, Japanese is one of the difficult languages.","id":"Bagi orang asing, bahasa Jepang adalah salah satu bahasa yang sulit."}]},{"pattern":"～によって (〜ni yotte)","meaning":"Indicates the reason or cause, difference depending on a factor, or methods used.","meaningId":"Menunjukkan alasan atau sebab, perbedaan tergantung pada suatu faktor, atau metode yang digunakan.","formation":"Verb-casual + によって, い-Adjective + によって, な-Adjective + によって, Noun + によって","formationId":"Kata Kerja-kasual + によって, い-Kata Sifat + によって, な-Kata Sifat + によって, Kata Benda + によって","examples":[{"jp":"その事故は悪天候によって引き起こされた。","romaji":"Sono jiko wa akutenkou ni yotte hikiokosareta.","en":"The accident was caused by bad weather.","id":"Kecelakaan itu disebabkan oleh cuaca buruk."},{"jp":"生活習慣によって、健康状態が変わります。","romaji":"Seikatsu shuukan ni yotte, kenkou joutai ga kawarimasu.","en":"Health conditions change depending on lifestyle habits.","id":"Kondisi kesehatan berubah tergantung pada kebiasaan gaya hidup."},{"jp":"彼の成功は努力によって得られたものだ。","romaji":"Kare no seikou wa doryoku ni yotte erareta mono da.","en":"His success was achieved through hard work.","id":"Kesuksesannya diraih melalui kerja keras."},{"jp":"結果は試験の難易度によって異なります。","romaji":"Kekka wa shiken no nan'ido ni yotte kotonarimasu.","en":"The results vary depending on the difficulty of the exam.","id":"Hasilnya berbeda-beda tergantung tingkat kesulitan ujiannya."}]},{"pattern":"～によれば (〜ni yoreba)","meaning":"Means 'according to', 'based on' or 'by'.","meaningId":"Berarti 'menurut', 'berdasarkan' atau 'oleh'.","formation":"Noun + によれば","formationId":"Kata benda + によれば","examples":[{"jp":"天気予報によれば、明日は晴れるでしょう。","romaji":"Tenki yohou ni yoreba, ashita wa hareru deshou.","en":"According to the weather forecast, it will be sunny tomorrow.","id":"Menurut ramalan cuaca, besok akan cerah."},{"jp":"先生によれば、この問題は簡単だそうです。","romaji":"Sensei ni yoreba, kono mondai wa kantan da sou desu.","en":"According to the teacher, this problem seems to be easy.","id":"Menurut guru, soal ini sepertinya mudah."},{"jp":"調査によれば、若者の喫煙率が減っているということです。","romaji":"Chousa ni yoreba, wakamono no kitsuenritsu ga hette iru to iu koto desu.","en":"According to the survey, the smoking rate among young people is decreasing.","id":"Berdasarkan survei, angka merokok di kalangan anak muda mengalami penurunan."},{"jp":"新聞記事によれば、その企業は倒産の危機にあるらしい。","romaji":"Shinbun kiji ni yoreba, sono kigyou wa tousan no kiki ni aru rashii.","en":"According to the newspaper article, the company appears to be on the verge of bankruptcy.","id":"Menurut artikel surat kabar tersebut, perusahaan tersebut tampaknya berada di ambang kebangkrutan."}]},{"pattern":"～に対して","meaning":"Indicates a target or contrast; 'toward', 'against', 'in contrast to', 'in response to'.","meaningId":"Menunjukkan target atau kontras; 'menuju', 'menentang', 'berlawanan dengan', 'menanggapi'.","formation":"Verb-casual + に対して, い-Adjective + に対して, な-Adjective + に対して, Noun + に対して","formationId":"Kata Kerja-kasual + に対して, い-Kata Sifat + に対して, な-Kata Sifat + に対して, Kata Benda + に対して","examples":[{"jp":"子供たちに対して、親は常にやさしくあるべきです。","romaji":"Kodomotachi ni taishite, oya wa tsune ni yasashiku aru beki desu.","en":"Parents should always be kind towards their children.","id":"Orang tua harus selalu bersikap baik terhadap anak-anaknya."},{"jp":"彼は質問に対して正直に答えました。","romaji":"Kare wa shitsumon ni taishite shoujiki ni kotaemashita.","en":"He answered the questions honestly.","id":"Dia menjawab pertanyaan-pertanyaan itu dengan jujur."},{"jp":"田中さんは成功したに対して、佐藤さんは失敗しました。","romaji":"Tanaka-san wa seikou shita ni taishite, Satou-san wa shippai shimashita.","en":"In contrast to Tanaka-san's success, Satou-san failed.","id":"Berbeda dengan kesuksesan Tanaka-san, Satou-san gagal."},{"jp":"彼の意見に対して、私は反対の立場を取りました。","romaji":"Kare no iken ni taishite, watashi wa hantai no tachiba wo torimashita.","en":"In response to his opinion, I took an opposing stance.","id":"Menanggapi pendapatnya, saya mengambil sikap menentang."}]},{"pattern":"～に比べて (〜ni kurabete)","meaning":"Comparing to; in comparison with; as opposed to.","meaningId":"Dibandingkan dengan; dibandingkan dengan; sebagai lawan dari.","formation":"Verb-casual + に比べて, い-Adjective + に比べて, な-Adjective + だ/である + に比べて, Noun + だ/である + に比べて","formationId":"Kata Kerja-kasual + に比べて, い-Kata Sifat + に比べて, な-Kata Sifat + だ/である + に比べて, Kata Benda + だ/である + に比べて","examples":[{"jp":"夏に比べて、冬は寒いです。","romaji":"Natsu ni kurabete, fuyu wa samui desu.","en":"Winter is cold compared to summer.","id":"Musim dingin lebih dingin dibandingkan musim panas."},{"jp":"このトマトは赤いトマトに比べて美味しくない。","romaji":"Kono tomato wa akai tomato ni kurabete oishikunai.","en":"This tomato is not as delicious compared to the red tomatoes.","id":"Tomat ini tidak selezat tomat merah."},{"jp":"彼は私に比べて英語が上手です。","romaji":"Kare wa watashi ni kurabete eigo ga jouzu desu.","en":"He is better at English compared to me.","id":"Dia lebih baik dalam bahasa Inggris dibandingkan dengan saya."},{"jp":"東京に比べて、京都は静かな町です。","romaji":"Toukyou ni kurabete, Kyouto wa shizukana machi desu.","en":"Kyoto is a quieter city compared to Tokyo.","id":"Kyoto adalah kota yang lebih tenang dibandingkan dengan Tokyo."}]},{"pattern":"～に関して (〜ni kanshite)","meaning":"Regarding, concerning, about, with respect to.","meaningId":"Mengenai, mengenai, mengenai, sehubungan dengan.","formation":"Noun + に関して","formationId":"Kata benda + に関して","examples":[{"jp":"健康に関して気を付けることが大切です。","romaji":"Kenkou ni kanshite ki wo tsukeru koto ga taisetsu desu.","en":"It is important to be careful regarding health.","id":"Penting untuk berhati-hati mengenai kesehatan."},{"jp":"このプロジェクトに関しては、彼がすべての詳細を知っています。","romaji":"Kono purojekuto ni kanshite wa, kare ga subete no shousai wo shitteimasu.","en":"Regarding this project, he knows all the details.","id":"Mengenai proyek ini, dia mengetahui semua detailnya."},{"jp":"環境問題に関して、私たちはもっと責任を持たなければなりません。","romaji":"Kankyou mondai ni kanshite, watashitachi wa motto sekinin wo motanakereba narimasen.","en":"Concerning environmental issues, we must take more responsibility.","id":"Terkait masalah lingkungan hidup, kita harus lebih bertanggung jawab."},{"jp":"この事件に関しての情報はまだ十分ではありません。","romaji":"Kono jiken ni kanshite no jouhou wa mada juubun de wa arimasen.","en":"The information regarding this incident is still insufficient.","id":"Informasi mengenai kejadian ini masih kurang."}]},{"pattern":"～の～ (〜no 〜)","meaning":"Indicates possession, attribution, or connection between two nouns.","meaningId":"Menunjukkan kepemilikan, atribusi, atau hubungan antara dua kata benda.","formation":"Noun1 + の + Noun2","formationId":"Kata Benda1 + の + Kata Benda2","examples":[{"jp":"これは私の傘です。","romaji":"Kore wa watashi no kasa desu.","en":"This is my umbrella.","id":"Ini payungku."},{"jp":"あのビルは東京の有名な観光スポットです。","romaji":"Ano biru wa Toukyou no yuumei na kankou supotto desu.","en":"That building is a famous tourist spot in Tokyo.","id":"Gedung itu merupakan tempat wisata terkenal di Tokyo."},{"jp":"彼は部長の秘書です。","romaji":"Kare wa buchou no hisho desu.","en":"He is the chief's secretary.","id":"Dia adalah sekretaris kepala."},{"jp":"彼女は音楽の先生です。","romaji":"Kanojo wa ongaku no sensei desu.","en":"She is a music teacher.","id":"Dia adalah seorang guru musik."}]},{"pattern":"～ばかり (〜bakari)","meaning":"Expresses 'only', 'nothing but', 'always', 'just'.","meaningId":"Menyatakan 'hanya', 'tidak lain', 'selalu', 'hanya'.","formation":"Verb-ますstem + ばかり, い-Adjective + ばかり, な-Adjective + ばかり, Noun + ばかり","formationId":"Kata Kerja-ますbatang + ばかり, い-Kata Sifat + ばかり, な-Kata Sifat + ばかり, Kata Benda + ばかり","examples":[{"jp":"彼はゲームばかりしている。","romaji":"Kare wa geemu bakari shite iru.","en":"He is always playing games.","id":"Dia selalu bermain-main."},{"jp":"この部屋は綺麗なものばかりだ。","romaji":"Kono heya wa kirei na mono bakari da.","en":"This room has nothing but clean things.","id":"Ruangan ini hanya berisi barang-barang bersih."},{"jp":"彼女は勉強ばかりしていて、遊んでいる暇がない。","romaji":"Kanojo wa benkyou bakari shite ite, asonde iru hima ga nai.","en":"She is always studying and has no time to play.","id":"Dia selalu belajar dan tidak punya waktu untuk bermain."},{"jp":"彼の話は嘘ばかりで、信じることができない。","romaji":"Kare no hanashi wa uso bakari de, shinjiru koto ga dekinai.","en":"His words are nothing but lies, and I cannot believe them.","id":"Kata-katanya hanyalah kebohongan, dan aku tidak dapat mempercayainya."}]},{"pattern":"～ばかりか (〜bakarika) ～も","meaning":"Not only... but also; more than just; not just","meaningId":"Tidak hanya... tetapi juga; lebih dari sekedar; tidak hanya","formation":"Verb-casual + ばかりか/も, い-Adjective + ばかりか/も, な-Adjective + だ + ばかりか/も, Noun + だ + ばかりか/も","formationId":"Kata Kerja-kasual + ばかりか/も, い-Kata Sifat + ばかりか/も, な-Kata Sifat + だ + ばかりか/も, Kata Benda + だ + ばかりか/も","examples":[{"jp":"彼女は英語ばかりか、フランス語も話せます。","romaji":"Kanojo wa eigo bakarika, furansugo mo hanasemasu.","en":"Not only can she speak English, but she can also speak French.","id":"Dia tidak hanya bisa berbahasa Inggris, tapi dia juga bisa berbahasa Prancis."},{"jp":"このレストランは味が良いばかりか、サービスも素晴らしい。","romaji":"Kono resutoran wa aji ga yoi bakarika, saabisu mo subarashii.","en":"Not only does this restaurant have great taste, but the service is also wonderful.","id":"Restoran ini tidak hanya memiliki cita rasa yang enak, tetapi layanannya juga luar biasa."},{"jp":"パーティは楽しかったばかりか、料理も美味しかった。","romaji":"Paatii wa tanoshikatta bakarika, ryouri mo oishikatta.","en":"Not only was the party fun, but the food was also delicious.","id":"Tidak hanya pestanya yang menyenangkan, tapi makanannya juga enak."},{"jp":"彼は頭がいいばかりか、スポーツも得意だ。","romaji":"Kare wa atama ga ii bakarika, supootsu mo tokui da.","en":"Not only is he smart, but he is also good at sports.","id":"Dia tidak hanya pintar, tapi dia juga pandai olahraga."}]},{"pattern":"～はずだ (〜hazu da)","meaning":"Expresses an expectation, 'should' or 'it is supposed to'.","meaningId":"Mengungkapkan harapan, 'seharusnya' atau 'seharusnya'.","formation":"Verb-casual + はずだ, い-Adjective + はずだ, な-Adjective + なはずだ, Noun + のはずだ","formationId":"Kata Kerja-kasual + はずだ, い-Kata Sifat + はずだ, な-Kata Sifat + なはずだ, Kata Benda + のはずだ","examples":[{"jp":"彼はもう着いたはずだ。","romaji":"Kare wa mou tsuita hazu da.","en":"He should have arrived by now.","id":"Dia seharusnya sudah tiba sekarang."},{"jp":"この薬を飲むと、痛みがなくなるはずだ。","romaji":"Kono kusuri wo nomu to, itami ga nakunaru hazu da.","en":"If you take this medicine, the pain should go away.","id":"Jika Anda meminum obat ini, rasa sakitnya akan hilang."},{"jp":"明日は晴れるはずだ。","romaji":"Ashita wa hareru hazu da.","en":"It is supposed to be sunny tomorrow.","id":"Besok seharusnya cerah."},{"jp":"彼女は元気なはずだ。","romaji":"Kanojo wa genki na hazu da.","en":"She is supposed to be well.","id":"Dia seharusnya baik-baik saja."}]},{"pattern":"～ば～のに (〜ba 〜noni)","meaning":"Expresses regret or dissatisfaction; 'if only', 'wish'.","meaningId":"Mengekspresikan penyesalan atau ketidakpuasan; 'kalau saja', 'berharap'.","formation":"Verb-ば form + ～のに, い-Adjective-ば form + ～のに, な-Adjective + であれば + ～のに, Noun + であれば + ～のに","formationId":"Bentuk kata kerja-ば + ～のに, bentuk い-Kata Sifat-ば + ～のに, な-Kata Sifat + であれば + ～のに, Kata Benda + であれば + ～のに","examples":[{"jp":"もっと早く来れば、電車に間に合ったのに。","romaji":"Motto hayaku kureba, densha ni maniatta noni.","en":"If only I had come earlier, I would have made it to the train.","id":"Kalau saja aku datang lebih awal, aku pasti bisa sampai ke kereta."},{"jp":"もっと勉強すれば、試験に合格したのに。","romaji":"Motto benkyou sureba, shiken ni goukaku shita noni.","en":"I wish I had studied more, I would have passed the exam.","id":"Saya berharap saya belajar lebih banyak, saya akan lulus ujian."},{"jp":"彼女がもっと優しければ、彼と上手くいくのに。","romaji":"Kanojo ga motto yasashikereba, kare to umaku iku noni.","en":"If only she were kinder, she would get along with him.","id":"Kalau saja dia lebih baik hati, dia akan rukun dengannya."},{"jp":"日本語が上手であれば、この本が読めるのに。","romaji":"Nihongo ga jouzu de areba, kono hon ga yomeru noni.","en":"I wish I were good at Japanese, then I could read this book.","id":"Saya berharap saya bisa berbahasa Jepang dengan baik, lalu saya bisa membaca buku ini."}]},{"pattern":"～ば～ほど (〜ba 〜hodo)","meaning":"Expresses 'the more ~, the more ~'; a proportional relationship between two phrases.","meaningId":"Menyatakan 'semakin ~, semakin banyak ~'; hubungan proporsional antara dua frase.","formation":"Verb-casual + ば + Verb-casual + ほど, い-Adjective + ば + い-Adjective + ほど, な-Adjective + であれば + な-Adjective + ほど","formationId":"Kata kerja-kasual + ば + Kata kerja-kasual + ほど, い-Kata Sifat + ば + い-Kata Sifat + ほど, な-Kata Sifat + であれば + な-Kata Sifat + ほど","examples":[{"jp":"早く起きれば起きるほど、時間がたくさんある。","romaji":"Hayaku okireba okiru hodo, jikan ga takusan aru.","en":"The earlier you wake up, the more time you have.","id":"Semakin awal Anda bangun, semakin banyak waktu yang Anda miliki."},{"jp":"練習すればするほど、上達します。","romaji":"Renshuu sureba suru hodo, joutatsu shimasu.","en":"The more you practice, the more you will improve.","id":"Semakin banyak Anda berlatih, semakin banyak Anda akan meningkat."},{"jp":"料理が美味しければ美味しいほど、皆が喜びます。","romaji":"Ryouri ga oishikereba oishii hodo, mina ga yorokobimasu.","en":"The more delicious the food is, the happier everyone will be.","id":"Semakin lezat makanannya, semakin bahagia semua orang."},{"jp":"日本語が上手であれば上手なほど、日本の生活が楽になります。","romaji":"Nihongo ga jouzu de areba jouzu na hodo, Nihon no seikatsu ga raku ni narimasu.","en":"The better your Japanese is, the easier life in Japan will be.","id":"Semakin baik bahasa Jepang Anda, kehidupan di Jepang akan semakin mudah."}]},{"pattern":"～はもちろん～も (〜wa mochiron 〜mo)","meaning":"Used for emphasizing that not only one thing but also another thing is included. It means 'not only... but also' or 'of course... and...'.","meaningId":"Digunakan untuk menekankan bahwa tidak hanya satu hal tetapi juga hal lain yang disertakan. Artinya 'tidak hanya... tetapi juga' atau 'tentu saja... dan...'.","formation":"Noun1 + はもちろん + Noun2 + も","formationId":"Kata Benda1 + はもちろん + Kata Benda2 + も","examples":[{"jp":"彼は数学はもちろん、英語も得意です。","romaji":"Kare wa suugaku wa mochiron, eigo mo tokui desu.","en":"Not only is he good at math, but he is also good at English.","id":"Dia tidak hanya pandai matematika, tetapi dia juga pandai bahasa Inggris."},{"jp":"このレストランは和食はもちろん、洋食も美味しいです。","romaji":"Kono resutoran wa washoku wa mochiron, youshoku mo oishii desu.","en":"This restaurant not only has delicious Japanese food but also delicious Western food.","id":"Restoran ini tidak hanya menyajikan makanan Jepang yang lezat tetapi juga makanan Barat yang lezat."},{"jp":"私の趣味は音楽はもちろん、読書も大好きです。","romaji":"Watashi no shumi wa ongaku wa mochiron, dokusho mo daisuki desu.","en":"My hobbies are not only listening to music, but I also love reading.","id":"Hobiku tidak hanya mendengarkan musik, tapi aku juga suka membaca."},{"jp":"東京は観光はもちろん、ビジネスも盛んです。","romaji":"Toukyou wa kankou wa mochiron, bijinesu mo sakan desu.","en":"Tokyo is not only famous for sightseeing but also has a thriving business scene.","id":"Tokyo tidak hanya terkenal dengan wisatanya tetapi juga memiliki dunia bisnis yang berkembang."}]},{"pattern":"～ばよかった (〜ba yokatta)","meaning":"Express a sense of regret; 'I wish', 'it would have been better if'.","meaningId":"Mengungkapkan rasa penyesalan; 'Saya berharap', 'akan lebih baik jika'.","formation":"Verb-ば-form + よかった, い-Adjective-く + ばよかった, な-Adjective + ならよかった","formationId":"Kata Kerja-ば-bentuk + よかった, い-Kata Sifat-く + ばよかった, な-Kata Sifat + ならよかった","examples":[{"jp":"もっと早く起きればよかった。","romaji":"Motto hayaku okireba yokatta.","en":"I wish I had woken up earlier.","id":"Saya berharap saya bangun lebih awal."},{"jp":"昨日のパーティーに行けばよかった。","romaji":"Kinou no paatii ni ikeba yokatta.","en":"I wish I had gone to yesterday's party.","id":"Saya berharap saya pergi ke pesta kemarin."},{"jp":"もっと安いものを買えばよかった。","romaji":"Motto yasui mono wo kaeba yokatta.","en":"I wish I had bought something cheaper.","id":"Saya berharap saya membeli sesuatu yang lebih murah."},{"jp":"あの時、もっと勉強すればよかった。","romaji":"Ano toki, motto benkyou sureba yokatta.","en":"I wish I had studied more at that time.","id":"Saya berharap saya telah belajar lebih banyak pada saat itu."}]},{"pattern":"～ふりをする (〜furi wo suru)","meaning":"Pretending or acting as if; 'pretend', 'act like'.","meaningId":"Berpura-pura atau bertindak seolah-olah; 'berpura-pura', 'bertindak seperti'.","formation":"Verb (dictionary form) + ふりをする, い-Adjective + ふりをする, な-Adjective + ふりをする, Noun + ふりをする","formationId":"Kata Kerja (bentuk kamus) + ふりをする, い-Kata Sifat + ふりをする, な-Kata Sifat + ふりをする, Kata Benda + ふりをする","examples":[{"jp":"彼は知らないふりをしました。","romaji":"Kare wa shiranai furi wo shimashita.","en":"He pretended not to know.","id":"Dia pura-pura tidak tahu."},{"jp":"彼女は病気のふりをして、学校を休みました。","romaji":"Kanojo wa byouki no furi wo shite, gakkou wo yasumimashita.","en":"She pretended to be sick and skipped school.","id":"Dia berpura-pura sakit dan bolos sekolah."},{"jp":"彼は嬉しいふりをしていますが、本当は悲しいです。","romaji":"Kare wa ureshii furi wo shiteimasu ga, hontou wa kanashii desu.","en":"He is pretending to be happy, but he is actually sad.","id":"Dia berpura-pura bahagia, tapi sebenarnya dia sedih."},{"jp":"彼女はリーダーのふりをして、チームを率いました。","romaji":"Kanojo wa riidaa no furi wo shite, chiimu wo hikimashita.","en":"She pretended to be a leader and led the team.","id":"Dia berpura-pura menjadi pemimpin dan memimpin tim."}]},{"pattern":"～べきだ (〜beki da)","meaning":"Express an obligation or something that should be done (mainly with verbs).","meaningId":"Menyatakan suatu kewajiban atau sesuatu yang harus dilakukan (terutama dengan kata kerja).","formation":"Verb-dictionary form + べきだ","formationId":"Bentuk kamus kata kerja + べきだ","examples":[{"jp":"勉強するべきだ。","romaji":"Benkyou suru beki da.","en":"You should study.","id":"Anda harus belajar."},{"jp":"早く寝るべきだ。","romaji":"Hayaku neru beki da.","en":"You should sleep early.","id":"Anda harus tidur lebih awal."},{"jp":"静かにするべきだ。","romaji":"Shizuka ni suru beki da.","en":"You should be quiet.","id":"Anda harus diam."},{"jp":"彼に謝るべきだ。","romaji":"Kare ni ayamaru beki da.","en":"You should apologize to him.","id":"Anda harus meminta maaf padanya."}]},{"pattern":"～ほど～ (〜hodo〜)","meaning":"Expresses the degree or extent; 'about', 'to the extent', 'as much as'.","meaningId":"Menyatakan derajat atau luasnya; 'tentang', 'sejauh', 'sebanyak'.","formation":"Verb-casual + ほど, い-Adjective + ほど, な-Adjective + ほど, Noun + ほど","formationId":"Kata Kerja-kasual + ほど, い-Kata Sifat + ほど, な-Kata Sifat + ほど, Kata Benda + ほど","examples":[{"jp":"彼女は私ほど速く走ることができません。","romaji":"Kanojo wa watashi hodo hayaku hashiru koto ga dekimasen.","en":"She cannot run as fast as me.","id":"Dia tidak bisa berlari secepat aku."},{"jp":"このケーキはあのケーキほど美味しくない。","romaji":"Kono keeki wa ano keeki hodo oishikunai.","en":"This cake is not as delicious as that cake.","id":"Kue ini tidak selezat kue itu."},{"jp":"日本ほど四季がはっきりしている国はない。","romaji":"Nihon hodo shiki ga hakkiri shite iru kuni wa nai.","en":"There is no country with as distinct seasons as Japan.","id":"Tidak ada negara dengan musim yang berbeda seperti Jepang."},{"jp":"東京は大阪ほど人が多くない。","romaji":"Toukyou wa Oosaka hodo hito ga ookunai.","en":"Tokyo does not have as many people as Osaka.","id":"Tokyo tidak memiliki penduduk sebanyak Osaka."}]},{"pattern":"～ますように (〜masu you ni)","meaning":"Used to express a wish or hope for oneself or someone else.","meaningId":"Digunakan untuk mengungkapkan keinginan atau harapan terhadap diri sendiri atau orang lain.","formation":"Verb-ます form, remove final る + ように","formationId":"Bentuk kata kerja-ます, hapus akhiran る + ように","examples":[{"jp":"明日のテストで良い点をとりますように。","romaji":"Ashita no tesuto de ii ten wo torimasu you ni.","en":"I hope I get good grades on tomorrow's test.","id":"Aku harap aku mendapat nilai bagus pada ulangan besok."},{"jp":"彼が無事に帰ってきますように。","romaji":"Kare ga buji ni kaette kimasu you ni.","en":"I hope he comes back safely.","id":"Saya harap dia kembali dengan selamat."},{"jp":"みんなが健康でいられますように。","romaji":"Minna ga kenkou de iraremasu you ni.","en":"I hope everyone stays healthy.","id":"Saya harap semua orang tetap sehat."},{"jp":"彼女に幸せになりますように。","romaji":"Kanojo ni shiawase ni narimasu you ni.","en":"I hope she becomes happy.","id":"Saya berharap dia menjadi bahagia."}]},{"pattern":"まったく～ない","meaning":"Completely not; not at all.","meaningId":"Sama sekali tidak; sama sekali tidak.","formation":"まったく + Verb-negative, まったく + い-Adjective-negative, まったく + な-Adjective-negative","formationId":"まったく + Kata Kerja-negatif, まったく + い-Kata Sifat-negatif, まったく + な-Kata Sifat-negatif","examples":[{"jp":"彼は、まったく覚えていない。","romaji":"Kare wa, mattaku oboete inai.","en":"He doesn't remember at all.","id":"Dia tidak ingat sama sekali."},{"jp":"この部屋はまったく暖かくない。","romaji":"Kono heya wa mattaku atatakakunai.","en":"This room is not warm at all.","id":"Ruangan ini sama sekali tidak hangat."},{"jp":"彼女はまったく遅れていない。","romaji":"Kanojo wa mattaku okurete inai.","en":"She is not late at all.","id":"Dia tidak terlambat sama sekali."},{"jp":"これはまったく便利ではない。","romaji":"Kore wa mattaku benri de wa nai.","en":"This is not convenient at all.","id":"Ini sama sekali tidak nyaman."}]},{"pattern":"～まで (〜made)","meaning":"Express 'until', 'up to', or 'as far as' to indicate the end point of an action or range.","meaningId":"Ekspresikan 'sampai', 'hingga', atau 'sejauh' untuk menunjukkan titik akhir suatu tindakan atau rentang.","formation":"Verb-casual + まで, い-Adjective + まで, な-Adjective + まで, Noun + まで","formationId":"Kata kerja-kasual + まで, い-Kata Sifat + まで, な-Kata Sifat + まで, Kata Benda + まで","examples":[{"jp":"10時まで働きます。","romaji":"Ju-ji made hatarakimasu.","en":"I will work until 10 o'clock.","id":"Saya akan bekerja sampai jam 10."},{"jp":"東京まで電車で行きます。","romaji":"Toukyou made densha de ikimasu.","en":"I will go by train as far as Tokyo.","id":"Saya akan pergi dengan kereta api sampai ke Tokyo."},{"jp":"彼は疲れるまで走りました。","romaji":"Kare wa tsukareru made hashirimashita.","en":"He ran until he got tired.","id":"Dia berlari sampai dia lelah."},{"jp":"5ページまで読んでください。","romaji":"Go-peeji made yonde kudasai.","en":"Please read up to page 5.","id":"Silakan baca sampai halaman 5."}]},{"pattern":"～まま (〜mama)","meaning":"Expresses the state or condition remaining unchanged.","meaningId":"Menyatakan keadaan atau kondisi yang tidak berubah.","formation":"Verb-ます stem + まま, い-Adjective + まま, な-Adjective + なまま, Noun + のまま","formationId":"Kata kerja-ます batang + まま, い-Kata Sifat + まま, な-Kata Sifat + なまま, Kata Benda + のまま","examples":[{"jp":"部屋の窓を開けたまま寝ました。","romaji":"Heya no mado wo aketa mama nemashita.","en":"I slept with the window of the room open.","id":"Saya tidur dengan jendela kamar terbuka."},{"jp":"熱いままのコーヒーを飲んで、舌を焦がしました。","romaji":"Atsui mama no koohii wo nonde, shita wo kogashimashita.","en":"I drank the coffee while it was still hot and burned my tongue.","id":"Saya meminum kopinya selagi masih panas dan lidah saya terbakar."},{"jp":"彼は忙しいなまま、休みの日も仕事をしています。","romaji":"Kare wa isogashii na mama, yasumi no hi mo shigoto wo shiteimasu.","en":"He continues to be busy, working even on his days off.","id":"Dia terus sibuk, bekerja bahkan di hari liburnya."},{"jp":"彼女は故郷にいるまま、外国に行かないで仕事を見つけた。","romaji":"Kanojo wa furusato ni iru mama, gaikoku ni ikanaide shigoto wo mitsuketa.","en":"She found a job without going abroad, staying in her hometown.","id":"Dia mendapatkan pekerjaan tanpa pergi ke luar negeri, tinggal di kampung halamannya."}]},{"pattern":"まるで～よう","meaning":"Used to express a strong resemblance or similarity; 'as if', 'just like', 'as though'.","meaningId":"Digunakan untuk menyatakan kemiripan atau persamaan yang kuat; 'seolah-olah', 'seolah-olah', 'seolah-olah'.","formation":"まるで + phrase/sentence + よう","formationId":"まるで + frase/kalimat + よう","examples":[{"jp":"彼女はまるで天使のように美しい。","romaji":"Kanojo wa maru de tenshi no you ni utsukushii.","en":"She is as beautiful as an angel.","id":"Dia secantik bidadari."},{"jp":"彼はまるでロボットのように仕事をしている。","romaji":"Kare wa maru de robotto no you ni shigoto wo shite iru.","en":"He works as if he is a robot.","id":"Dia bekerja seolah-olah dia adalah robot."},{"jp":"あの家はまるでお城のようだ。","romaji":"Ano ie wa maru de oshiro no you da.","en":"That house is just like a castle.","id":"Rumah itu seperti kastil."},{"jp":"ここはまるで楽園のような場所です。","romaji":"Koko wa maru de rakuen no you na basho desu.","en":"This place is as though it's a paradise.","id":"Tempat ini seolah-olah merupakan surga."}]},{"pattern":"～てみる (〜te miru)","meaning":"A grammar structure used to express the action of trying or attempting something to see what happens.","meaningId":"Struktur tata bahasa yang digunakan untuk menyatakan tindakan mencoba atau mencoba sesuatu untuk melihat apa yang terjadi.","formation":"Verb-て form + みる","formationId":"Bentuk kata kerja-て + みる","examples":[{"jp":"彼は走ってみたが、まだ膝が痛いと感じた。","romaji":"Kare wa hashitte mita ga, mada hiza ga itai to kanjita.","en":"He tried running, but he still felt pain in his knee.","id":"Dia mencoba berlari, tapi lututnya masih terasa sakit."},{"jp":"彼女は料理を作ってみたが、失敗してしまった。","romaji":"Kanojo wa ryouri o tsukutte mita ga, shippai shite shimatta.","en":"She tried cooking but ended up failing.","id":"Dia mencoba memasak tetapi akhirnya gagal."},{"jp":"初めてのデートで、彼は彼女にサプライズをしようと考え、歌ってみた。","romaji":"Hajimete no deeto de, kare wa kanojo ni sapuraizu o shiyou to kangae, utatte mita.","en":"On their first date, he thought of surprising her and tried singing.","id":"Pada kencan pertama mereka, dia berpikir untuk mengejutkannya dan mencoba bernyanyi."},{"jp":"このケーキは美味しそうだから、味見に食べてみる。","romaji":"Kono keeki wa oishisou dakara, ajimi ni tabete miru.","en":"Since this cake looks delicious, I will try tasting it.","id":"Karena kue ini kelihatannya enak, saya akan mencoba mencicipinya."}]},{"pattern":"～みたいだ (〜mitai da)","meaning":"Express similarity or appearance; 'like', 'seems', 'looks'.","meaningId":"Mengungkapkan kesamaan atau penampilan; 'seperti', 'tampaknya', 'terlihat'.","formation":"Verb-casual + みたいだ, い-Adjective + みたいだ, な-Adjective + みたいだ, Noun + みたいだ","formationId":"Kata Kerja-kasual + みたいだ, い-Kata Sifat + みたいだ, な-Kata Sifat + みたいだ, Kata Benda + みたいだ","examples":[{"jp":"彼は怒っているみたいだ。","romaji":"Kare wa okotte iru mitai da.","en":"He seems to be angry.","id":"Dia sepertinya marah."},{"jp":"そのビルは古いみたいだ。","romaji":"Sono biru wa furui mitai da.","en":"That building looks old.","id":"Bangunan itu terlihat tua."},{"jp":"彼女は疲れているみたいだ。","romaji":"Kanojo wa tsukarete iru mitai da.","en":"She seems to be tired.","id":"Dia sepertinya lelah."},{"jp":"この料理は辛いみたいだ。","romaji":"Kono ryouri wa karai mitai da.","en":"This dish seems to be spicy.","id":"Hidangan ini sepertinya pedas."}]},{"pattern":"～めったに～ない (〜metta ni 〜nai)","meaning":"Used to express that something rarely, hardly ever or seldom happens.","meaningId":"Digunakan untuk menyatakan bahwa sesuatu yang jarang, hampir tidak pernah atau jarang terjadi.","formation":"めったに + Verb[ない-form] / めったに + い-Adjective[ない-form] / めったに + な-Adjective[じゃない/ではない-form]","formationId":"めったに + Kata Kerja[ない-bentuk] / めったに + い-Kata Sifat[ない-bentuk] / めったに + な-Kata Sifat[じゃない/ではない-bentuk]","examples":[{"jp":"彼はめったに外食しない。","romaji":"Kare wa metta ni gaishoku shinai.","en":"He hardly ever eats out.","id":"Dia hampir tidak pernah makan di luar."},{"jp":"私はめったに寿司を食べない。","romaji":"Watashi wa metta ni sushi wo tabenai.","en":"I seldom eat sushi.","id":"Saya jarang makan sushi."},{"jp":"この地域はめったに雪が降らない。","romaji":"Kono chiiki wa metta ni yuki ga furanai.","en":"It hardly ever snows in this area.","id":"Hampir tidak pernah turun salju di daerah ini."},{"jp":"彼女はめったに怒らない。","romaji":"Kanojo wa metta ni okoranai.","en":"She hardly ever gets angry.","id":"Dia hampir tidak pernah marah."}]},{"pattern":"～めったにない (〜metta ni nai)","meaning":"Expresses the rarity of an action, event or state; 'hardly', 'rarely', 'seldom'.","meaningId":"Mengekspresikan kelangkaan suatu tindakan, peristiwa atau keadaan; 'hampir tidak', 'jarang', 'jarang'.","formation":"Verb-negative + めったにない, い-Adjective-negative + めったにない, な-Adjective-negative + めったにない, Noun-negative + めったにない","formationId":"Kata kerja-negatif + めったにない, い-Kata sifat-negatif + めったにない, な-Kata sifat-negatif + めったにない, Kata benda-negatif +めったにない","examples":[{"jp":"この町では雪が降ることはめったにない。","romaji":"Kono machi de wa yuki ga furu koto wa metta ni nai.","en":"It hardly ever snows in this town.","id":"Jarang sekali turun salju di kota ini."},{"jp":"彼はめったに外食しない。","romaji":"Kare wa metta ni gaishoku shinai.","en":"He rarely eats out.","id":"Dia jarang makan di luar."},{"jp":"友達が遊びに来るのはめったにない。","romaji":"Tomodachi ga asobi ni kuru no wa metta ni nai.","en":"Friends seldom come to visit.","id":"Teman jarang datang berkunjung."},{"jp":"彼女はめったに怒らない。","romaji":"Kanojo wa metta ni okoranai.","en":"She hardly ever gets angry.","id":"Dia hampir tidak pernah marah."}]},{"pattern":"もしかすると〜かもしれない (moshikasuru to 〜kamoshirenai)","meaning":"Express the possibility of something; 'maybe', 'perhaps', 'might'.","meaningId":"Ekspresikan kemungkinan sesuatu; 'mungkin', 'mungkin', 'mungkin'.","formation":"もしかすると + Sentence + かもしれない","formationId":"もしかすると + Kalimat + かもしれない","examples":[{"jp":"もしかすると彼は遅刻するかもしれない。","romaji":"Moshikasuru to kare wa chikoku suru kamoshirenai.","en":"Maybe he might be late.","id":"Mungkin dia mungkin terlambat."},{"jp":"もしかすると彼女は疲れているかもしれない。","romaji":"Moshikasuru to kanojo wa tsukarete iru kamoshirenai.","en":"Perhaps she might be tired.","id":"Mungkin dia lelah."},{"jp":"もしかすると雨が降るかもしれない。","romaji":"Moshikasuru to ame ga furu kamoshirenai.","en":"It might rain, maybe.","id":"Mungkin akan turun hujan, mungkin."},{"jp":"もしかすると彼らはその映画が好きじゃないかもしれない。","romaji":"Moshikasuru to karera wa sono eiga ga suki janai kamoshirenai.","en":"Maybe they might not like that movie.","id":"Mungkin mereka mungkin tidak menyukai film itu."}]},{"pattern":"もし～たなら","meaning":"Express a hypothetical condition, 'if' or 'in case'.","meaningId":"Nyatakan kondisi hipotetis, 'jika' atau 'seandainya'.","formation":"もし + Verb-casual past + なら, もし + い-Adjective-casual past + なら, もし + な-Adjective + だったなら, もし + Noun + だったなら","formationId":"もし + Verb-casual past + なら, もし + い-Adjective-casual past + なら, もし + な-Adjective + だったなら, もし + Noun + だったなら","examples":[{"jp":"もし雨が降ったなら、傘を持って行きましょう。","romaji":"Moshi ame ga futta nara, kasa wo motte ikimashou.","en":"If it rains, let's bring an umbrella.","id":"Kalau hujan ayo bawa payung."},{"jp":"もしケーキが美味しくなかったなら、誰も食べないでしょう。","romaji":"Moshi keeki ga oishikunakatta nara, daremo tabenai deshou.","en":"If the cake was not delicious, nobody would eat it.","id":"Jika kuenya tidak enak, tidak ada yang akan memakannya."},{"jp":"もし彼が病気だったなら、すぐに病院に行かせてあげてください。","romaji":"Moshi kare ga byouki datta nara, sugu ni byouin ni ikasete agete kudasai.","en":"If he was sick, please take him to the hospital right away.","id":"Jika dia sakit, tolong segera bawa dia ke rumah sakit."},{"jp":"もし彼女が学生だったなら、このレストランは割引があるでしょう。","romaji":"Moshi kanojo ga gakusei datta nara, kono resutoran wa waribiki ga aru deshou.","en":"If she were a student, there would be a discount at this restaurant.","id":"Jika dia seorang pelajar, akan ada diskon di restoran ini."}]},{"pattern":"もし～ても","meaning":"Express a hypothetical situation or assumption with the nuance of 'even if'.","meaningId":"Ekspresikan situasi atau asumsi hipotetis dengan nuansa 'sekalipun'.","formation":"もし + Verb-て form + も / もし + い-Adjective(く) + ても / もし + な-Adjective/Noun + でも","formationId":"もし + Bentuk kata kerja-て + も / もし + い-Kata Sifat(く) + ても / もし + な-Kata Sifat/Kata Benda + でも","examples":[{"jp":"もし雨が降っても、ピクニックに行きます。","romaji":"Moshi ame ga futtemo, pikunikku ni ikimasu.","en":"Even if it rains, we will go on a picnic.","id":"Meski hujan, kami akan tetap piknik."},{"jp":"もし彼が謝っても、まだ怒っているでしょう。","romaji":"Moshi kare ga ayamattemo, mada okotteiru deshou.","en":"Even if he apologizes, I will still be angry.","id":"Meski dia meminta maaf, aku tetap akan marah."},{"jp":"もし試験に合格しても、まだ勉強を続けます。","romaji":"Moshi shiken ni goukaku shitemo, mada benkyou wo tsuzukemasu.","en":"Even if I pass the exam, I will still continue studying.","id":"Sekalipun aku lulus ujian, aku akan tetap melanjutkan belajar."},{"jp":"もし彼女が遅く来ても、待っています。","romaji":"Moshi kanojo ga osoku kite mo, matteimasu.","en":"Even if she comes late, I will wait.","id":"Walaupun dia datang terlambat, aku akan menunggunya."}]},{"pattern":"もしも～なら","meaning":"Express a hypothetical condition or situation; 'if', 'in case', 'suppose'.","meaningId":"Menyatakan suatu kondisi atau situasi hipotetis; 'jika', 'seandainya', 'seandainya'.","formation":"Verb-casual + なら, い-Adjective + なら, な-Adjective + なら, Noun + なら","formationId":"Kata Kerja-kasual + なら, い-Kata Sifat + なら, な-Kata Sifat + なら, Kata Benda + なら","examples":[{"jp":"もしも明日雨が降ったなら、出かけません。","romaji":"Moshimo ashita ame ga futta nara, dekakemasen.","en":"If it rains tomorrow, I won't go out.","id":"Jika besok hujan, saya tidak akan keluar."},{"jp":"もしも彼が来なかったなら、私たちだけでパーティーをします。","romaji":"Moshimo kare ga konakatta nara, watashitachi dake de paatii wo shimasu.","en":"If he doesn't come, we'll have the party just by ourselves.","id":"Jika dia tidak datang, kita akan mengadakan pestanya sendiri."},{"jp":"もしも彼女が疲れているなら、休ませてあげてください。","romaji":"Moshimo kanojo ga tsukarete iru nara, yasumasete agete kudasai.","en":"If she is tired, please let her rest.","id":"Jika dia lelah, tolong biarkan dia istirahat."},{"jp":"もしもそれが真実なら、認めなければなりません。","romaji":"Moshimo sore ga shinjitsu nara, mitomenakereba narimasen.","en":"If that is true, we have to admit it.","id":"Jika itu benar, kita harus mengakuinya."}]},{"pattern":"～ようとしない (〜you to shinai)","meaning":"Not showing any sign or intention to do something.","meaningId":"Tidak menunjukkan tanda atau niat untuk melakukan sesuatu.","formation":"Verb-volitional form + としない","formationId":"Bentuk kata kerja-kehendak + としない","examples":[{"jp":"彼は勉強しようとしない。","romaji":"Kare wa benkyou shiyou to shinai.","en":"He doesn't show any sign of trying to study.","id":"Dia tidak menunjukkan tanda-tanda mencoba belajar."},{"jp":"彼女は謝ろうとしない。","romaji":"Kanojo wa ayamarou to shinai.","en":"She doesn't show any intention of apologizing.","id":"Dia tidak menunjukkan niat untuk meminta maaf."},{"jp":"息子は部屋を片付けようとしない。","romaji":"Musuko wa heya wo katazuke you to shinai.","en":"My son doesn't show any intention of cleaning his room.","id":"Anak saya tidak menunjukkan niat untuk membersihkan kamarnya."},{"jp":"犬は散歩に行こうとしない。","romaji":"Inu wa sanpo ni ikou to shinai.","en":"The dog doesn't show any sign of wanting to go for a walk.","id":"Anjing itu tidak menunjukkan tanda-tanda ingin berjalan-jalan."}]},{"pattern":"～ようと思う (〜you to omou)","meaning":"Expresses the speaker's intention or plan to do something.","meaningId":"Mengungkapkan maksud atau rencana pembicara untuk melakukan sesuatu.","formation":"Verb-volitional + と思う","formationId":"Kata kerja-kehendak + と思う","examples":[{"jp":"今日は早く寝ようと思います。","romaji":"Kyou wa hayaku neyou to omoimasu.","en":"I think I will go to bed early today.","id":"Saya pikir saya akan tidur lebih awal hari ini."},{"jp":"明日美術館に行こうと思っています。","romaji":"Ashita bijutsukan ni ikou to omotteimasu.","en":"I am planning to go to the art museum tomorrow.","id":"Saya berencana pergi ke museum seni besok."},{"jp":"新しいカメラを買おうと思います。","romaji":"Atarashii kamera wo kaou to omoimasu.","en":"I think I will buy a new camera.","id":"Saya pikir saya akan membeli kamera baru."},{"jp":"来週友達と映画を見ようと思っています。","romaji":"Raishuu tomodachi to eiga wo miyou to omotteimasu.","en":"I am planning to watch a movie with my friend next week.","id":"Saya berencana menonton film bersama teman saya minggu depan."}]},{"pattern":"～ように (〜you ni)","meaning":"Expressing a purpose, a goal or a way of doing something; 'in order to', 'so that', 'like', 'as'","meaningId":"Mengekspresikan tujuan, sasaran atau cara melakukan sesuatu; 'untuk', 'sehingga', 'seperti', 'sebagai'","formation":"Verb-casual + ように, い-Adjective + ように, な-Adjective + に, Noun + のように","formationId":"Kata Kerja-kasual + ように, い-Kata Sifat + ように, な-Kata Sifat + に, Kata Benda + のように","examples":[{"jp":"早く家に帰るように、仕事を急いで終わらせました。","romaji":"Hayaku ie ni kaeru you ni, shigoto wo isoide owarasemashita.","en":"In order to get home early, I hurried to finish my work.","id":"Agar bisa pulang lebih awal, aku bergegas menyelesaikan pekerjaanku."},{"jp":"彼女は美しい花のように見えました。","romaji":"Kanojo wa utsukushii hana no you ni miemashita.","en":"She looked like a beautiful flower.","id":"Dia tampak seperti bunga yang indah."},{"jp":"この部屋がきれいになるように、掃除をしましょう。","romaji":"Kono heya ga kirei ni naru you ni, souji wo shimashou.","en":"Let's clean so that this room becomes clean.","id":"Mari kita bersihkan agar ruangan ini menjadi bersih."},{"jp":"山田さんは元気なように振る舞っていましたが、実際は疲れているらしいです。","romaji":"Yamada-san wa genki na you ni furumatte imashita ga, jissai wa tsukarete iru rashii desu.","en":"Yamada-san was acting as if he was energetic, but he actually seems to be tired.","id":"Yamada-san bertingkah seolah-olah dia energik, tapi sebenarnya dia terlihat lelah."}]},{"pattern":"～ように (〜you ni)","meaning":"Used to express a purpose, a way, or a natural tendency.","meaningId":"Digunakan untuk mengungkapkan tujuan, cara, atau kecenderungan alami.","formation":"Verb-casual + ように, い-Adjective + ように, な-Adjective + だように, Noun + のように","formationId":"Kata Kerja-kasual + ように, い-Kata Sifat + ように, な-Kata Sifat + だように, Kata Benda + のように","examples":[{"jp":"子供が安全に過ごせるように、家の中を整理します。","romaji":"Kodomo ga anzen ni sugoseru you ni, ie no naka wo seiri shimasu.","en":"I will organize the inside of the house so that the children can spend time safely.","id":"Saya akan menata bagian dalam rumah agar anak-anak dapat menghabiskan waktu dengan aman."},{"jp":"美しい花のように、彼女は笑顔が素敵です。","romaji":"Utsukushii hana no you ni, kanojo wa egao ga suteki desu.","en":"Like a beautiful flower, her smile is lovely.","id":"Seperti bunga yang indah, senyumnya indah."},{"jp":"自然に英語を話せるように、毎日練習しています。","romaji":"Shizen ni eigo wo hanaseru you ni, mainichi renshuu shiteimasu.","en":"I practice every day to be able to speak English naturally.","id":"Saya berlatih setiap hari untuk dapat berbicara bahasa Inggris secara alami."},{"jp":"成功するように、計画を立てましょう。","romaji":"Seikou suru you ni, keikaku wo tatemashou.","en":"Let's make a plan to succeed.","id":"Mari buat rencana untuk sukses."}]},{"pattern":"～ように (〜you ni)","meaning":"Used to express purpose or how something is done; 'like', 'as if', 'in order to'.","meaningId":"Digunakan untuk menyatakan tujuan atau bagaimana sesuatu dilakukan; 'seperti', 'seolah-olah', 'untuk'.","formation":"Verb-casual + ように, い-Adjective + ように, な-Adjective + に, Noun + のように","formationId":"Kata Kerja-kasual + ように, い-Kata Sifat + ように, な-Kata Sifat + に, Kata Benda + のように","examples":[{"jp":"分かりやすいように説明してください。","romaji":"Wakariyasui you ni setsumei shite kudasai.","en":"Please explain it in a way that is easy to understand.","id":"Mohon penjelasannya dengan cara yang mudah dimengerti."},{"jp":"彼は鳥のように歌います。","romaji":"Kare wa tori no you ni utaimasu.","en":"He sings like a bird.","id":"Dia bernyanyi seperti burung."},{"jp":"友達と仲良くするように努めています。","romaji":"Tomodachi to nakayoku suru you ni tsutometeimasu.","en":"I am trying to get along well with my friends.","id":"Saya berusaha bergaul dengan baik dengan teman-teman saya."},{"jp":"日本語が上手になるように勉強しています。","romaji":"Nihongo ga jouzu ni naru you ni benkyou shiteimasu.","en":"I am studying to become better at Japanese.","id":"Saya sedang belajar untuk menjadi lebih baik dalam bahasa Jepang."}]},{"pattern":"～ようにしましょう (〜you ni shimashou)","meaning":"A suggestion to make an effort or try to do something; 'let's try to', 'let's make sure to'.","meaningId":"Saran untuk berusaha atau mencoba melakukan sesuatu; 'mari kita coba', 'mari kita pastikan'.","formation":"Verb-dictionary form + ようにしましょう / Verb-negative form + ようにしましょう","formationId":"Bentuk kamus kata kerja + ようにしましょう ​​/ Bentuk kata kerja negatif + ようにしましょう","examples":[{"jp":"毎日運動するようにしましょう。","romaji":"Mainichi undou suru you ni shimashou.","en":"Let's try to exercise every day.","id":"Yuk, cobalah berolahraga setiap hari."},{"jp":"早く寝るようにしましょう。","romaji":"Hayaku neru you ni shimashou.","en":"Let's make sure to go to bed early.","id":"Mari kita pastikan untuk tidur lebih awal."},{"jp":"親切にするようにしましょう。","romaji":"Shinsetsu ni suru you ni shimashou.","en":"Let's try to be kind.","id":"Mari kita mencoba bersikap baik."},{"jp":"時間を無駄にしないようにしましょう。","romaji":"Jikan wo muda ni shinai you ni shimashou.","en":"Let's make sure not to waste time.","id":"Mari kita pastikan untuk tidak membuang waktu."}]},{"pattern":"～ようになった (〜you ni natta)","meaning":"Express an event or state that became possible; 'became able to', 'started to', 'now can'.","meaningId":"Menyatakan suatu peristiwa atau keadaan yang menjadi mungkin; 'menjadi mampu', 'mulai', 'sekarang bisa'.","formation":"Verb-casual + ようになった","formationId":"Kata kerja-kasual + ようになった","examples":[{"jp":"彼は料理を作るようになった。","romaji":"Kare wa ryouri wo tsukuru you ni natta.","en":"He became able to cook.","id":"Dia menjadi bisa memasak."},{"jp":"その子は読めるようになった。","romaji":"Sono ko wa yomeru you ni natta.","en":"That child started to be able to read.","id":"Anak itu mulai bisa membaca."},{"jp":"会議は週に一度開催されるようになった。","romaji":"Kaigi wa shuu ni ichido kaisai sareru you ni natta.","en":"The meeting started to be held once a week.","id":"Pertemuan mulai diadakan seminggu sekali."},{"jp":"日本語がわかるようになった。","romaji":"Nihongo ga wakaru you ni natta.","en":"I became able to understand Japanese.","id":"Saya menjadi bisa mengerti bahasa Jepang."}]},{"pattern":"～ように言う (〜you ni iu)","meaning":"To convey a message, instruction or request to someone; 'to tell (someone) to', 'to say to (someone)'.","meaningId":"Untuk menyampaikan pesan, instruksi atau permintaan kepada seseorang; 'untuk memberitahu (seseorang) untuk', 'untuk mengatakan kepada (seseorang)'.","formation":"Verb-dictionary form + ように言う / Verb-nai form + ように言う","formationId":"Bentuk kamus kata kerja + ように言う / Bentuk kata kerja-nai + ように言う","examples":[{"jp":"先生は私にもっと勉強するように言った。","romaji":"Sensei wa watashi ni motto benkyou suru you ni itta.","en":"The teacher told me to study more.","id":"Guru menyuruh saya untuk belajar lebih banyak."},{"jp":"彼女は彼に待つように言いました。","romaji":"Kanojo wa kare ni matsu you ni iimashita.","en":"She told him to wait.","id":"Dia menyuruhnya menunggu."},{"jp":"母は私に部屋を片付けるように言いました。","romaji":"Haha wa watashi ni heya wo katazukeru you ni iimashita.","en":"My mother told me to clean my room.","id":"Ibuku menyuruhku membersihkan kamarku."},{"jp":"先生は生徒に質問をするように言った。","romaji":"Sensei wa seito ni shitsumon wo suru you ni itta.","en":"The teacher told the student to ask a question.","id":"Guru menyuruh siswanya untuk mengajukan pertanyaan."}]},{"pattern":"～らしい (〜rashii)","meaning":"Expresses hearsay; 'I heard', 'it seems', 'apparently'.","meaningId":"Mengungkapkan desas-desus; 'Saya dengar', 'sepertinya', 'tampaknya'.","formation":"Verb-casual + らしい, い-Adjective + らしい, な-Adjective + だらしい, Noun + だらしい","formationId":"Kata Kerja-kasual + らしい, い-Kata Sifat + らしい, な-Kata Sifat + だらしい, Kata Benda + だらしい","examples":[{"jp":"彼はインフルエンザらしい。","romaji":"Kare wa infuruenza rashii.","en":"Apparently, he has the flu.","id":"Rupanya, dia terkena flu."},{"jp":"明日雪が降るらしい。","romaji":"Ashita yuki ga furu rashii.","en":"I heard it will snow tomorrow.","id":"Kudengar besok akan turun salju."},{"jp":"このレストランは美味しいらしい。","romaji":"Kono resutoran wa oishii rashii.","en":"I heard that this restaurant is delicious.","id":"Kudengar restoran ini enak."},{"jp":"彼女は医者だらしい。","romaji":"Kanojo wa isha darashii.","en":"It seems that she is a doctor.","id":"Sepertinya dia adalah seorang dokter."}]},{"pattern":"～られた (〜rareta)","meaning":"Express a passive action, 'was/were', 'has/have been'.","meaningId":"Ekspresikan tindakan pasif, 'dulu/sedang', 'telah/telah'.","formation":"Verb (passive form, past tense) + られた","formationId":"Kata Kerja (bentuk pasif, bentuk lampau) + られた","examples":[{"jp":"この本はたくさんの人に読まれた。","romaji":"Kono hon wa takusan no hito ni yomareta.","en":"This book was read by many people.","id":"Buku ini telah dibaca oleh banyak orang."},{"jp":"彼は友達に騙された。","romaji":"Kare wa tomodachi ni damasareta.","en":"He was deceived by his friend.","id":"Dia ditipu oleh temannya."},{"jp":"昨日、私の財布が盗まれました。","romaji":"Kinou, watashi no saifu ga nusumaremashita.","en":"Yesterday, my wallet was stolen.","id":"Kemarin, dompet saya dicuri."},{"jp":"彼女は映画に感動させられた。","romaji":"Kanojo wa eiga ni kandou saserareta.","en":"She was deeply moved by the movie.","id":"Dia sangat tersentuh oleh film tersebut."}]},{"pattern":"～ている (〜te iru)","meaning":"Expresses a continuing action or a resulting state; 'is ~ing', 'has been', 'has'.","meaningId":"Mengekspresikan tindakan yang berkelanjutan atau keadaan yang dihasilkan; 'adalah ~ing', 'telah', 'telah'.","formation":"Verb-て form + いる","formationId":"Bentuk kata kerja-て + いる","examples":[{"jp":"窓が開けられている。","romaji":"Mado ga akerarete iru.","en":"The window is open (someone opened it and it remains open).","id":"Jendela terbuka (seseorang membukanya dan tetap terbuka)."},{"jp":"ケーキが全部食べられている。","romaji":"Keeki ga zenbu taberarete iru.","en":"The whole cake has been eaten.","id":"Seluruh kue telah dimakan."},{"jp":"彼女は病気で寝込んでいる。","romaji":"Kanojo wa byouki de nekonde iru.","en":"She is bedridden due to illness.","id":"Dia terbaring di tempat tidur karena sakit."},{"jp":"宿題が終わっている。","romaji":"Shukudai ga owatte iru.","en":"The homework is finished (has been done).","id":"Pekerjaan rumah sudah selesai (sudah selesai)."}]},{"pattern":"～わけがない (〜wake ga nai)","meaning":"Expresses that something is impossible or unreasonable; 'there's no way', 'can't be'.","meaningId":"Menyatakan bahwa ada sesuatu yang tidak mungkin atau tidak masuk akal; 'tidak mungkin', 'tidak mungkin'.","formation":"Verb-casual + わけがない, い-Adjective + わけがない, な-Adjective + なわけがない, Noun + のわけがない","formationId":"Kata Kerja-kasual + わけがない, い-Kata Sifat + わけがない, な-Kata Sifat + なわけがない, Kata Benda + のわけがない","examples":[{"jp":"彼がそんなことを言うわけがない。","romaji":"Kare ga sonna koto wo iu wake ga nai.","en":"There's no way he would say something like that.","id":"Tidak mungkin dia mengatakan hal seperti itu."},{"jp":"あのレストランがまずいわけがない。","romaji":"Ano resutoran ga mazui wake ga nai.","en":"There's no way that restaurant tastes bad.","id":"Tidak mungkin restoran itu rasanya tidak enak."},{"jp":"彼女が優しくないわけがない。","romaji":"Kanojo ga yasashiku nai wake ga nai.","en":"There's no way she's not kind.","id":"Tidak mungkin dia tidak baik."},{"jp":"彼が試験に合格しないわけがない。","romaji":"Kare ga shiken ni goukaku shinai wake ga nai.","en":"There's no way he won't pass the exam.","id":"Tidak mungkin dia tidak lulus ujian."}]},{"pattern":"～わけだ (〜wake da)","meaning":"Expresses a logical conclusion or reason based on information; 'that's why', 'no wonder', 'it means'.","meaningId":"Mengungkapkan kesimpulan atau alasan logis berdasarkan informasi; 'itu sebabnya', 'pantas saja', 'artinya'.","formation":"Verb-casual + わけだ, い-Adjective + わけだ, な-Adjective + なわけだ, Noun + のわけだ","formationId":"Kata Kerja-kasual + わけだ, い-Kata Sifat + わけだ, な-Kata Sifat + なわけだ, Kata Benda + のわけだ","examples":[{"jp":"彼は風邪を引いている。だから、声がかすれているわけだ。","romaji":"Kare wa kaze wo hiite iru. Dakara, koe ga kasurete iru wake da.","en":"He has a cold. That's why his voice is hoarse.","id":"Dia sedang flu. Makanya suaranya serak."},{"jp":"今日は忙しかった。だから、疲れたわけだ。","romaji":"Kyou wa isogashikatta. Dakara, tsukareta wake da.","en":"Today was busy. No wonder I'm tired.","id":"Hari ini sibuk. Tidak heran aku lelah."},{"jp":"田中さんはたくさん勉強している。だから、試験に合格したわけだ。","romaji":"Tanaka-san wa takusan benkyou shite iru. Dakara, shiken ni goukaku shita wake da.","en":"Tanaka has been studying a lot. It means he passed the exam.","id":"Tanaka telah banyak belajar. Itu berarti dia lulus ujian."},{"jp":"彼女は有名な歌手の娘なんだ。だから、歌が上手なわけだ。","romaji":"Kanojo wa yuumei na kashu no musume nan da. Dakara, uta ga jouzu na wake da.","en":"She's the daughter of a famous singer. That's why she's good at singing.","id":"Dia putri seorang penyanyi terkenal. Itu sebabnya dia pandai menyanyi."}]},{"pattern":"～わけではない (〜wake dewa nai)","meaning":"Denies a general assumption; 'it does not mean that', 'it's not the case'.","meaningId":"Menyangkal asumsi umum; 'bukan berarti begitu', 'bukan begitu'.","formation":"Verb-casual + わけではない, い-Adjective + わけではない, な-Adjective + だわけではない, Noun + だわけではない","formationId":"Kata Kerja-kasual + わけではない, い-Kata Sifat + わけではない, な-Kata Sifat + だわけではない, Kata Benda + だわけではない","examples":[{"jp":"彼が忙しいからといって、友達がいないわけではない。","romaji":"Kare ga isogashii kara to itte, tomodachi ga inai wake dewa nai.","en":"Just because he's busy doesn't mean he has no friends.","id":"Hanya karena dia sibuk bukan berarti dia tidak punya teman."},{"jp":"この映画は面白くないわけではないが、好みではない。","romaji":"Kono eiga wa omoshirokunai wake dewa nai ga, konomi dewa nai.","en":"It's not that this movie isn't interesting; it's just not my taste.","id":"Bukan berarti film ini tidak menarik; itu bukan seleraku."},{"jp":"彼女が病気だからといって、毎日寝ているわけではない。","romaji":"Kanojo ga byouki dakara to itte, mainichi nete iru wake dewa nai.","en":"Just because she's sick doesn't mean she's in bed all day.","id":"Hanya karena dia sakit bukan berarti dia harus terbaring di tempat tidur sepanjang hari."},{"jp":"彼が大学に行っていないからといって、バカだわけではない。","romaji":"Kare ga daigaku ni itte inai kara to itte, baka da wake dewa nai.","en":"Just because he didn't go to college doesn't mean he's stupid.","id":"Hanya karena dia tidak kuliah bukan berarti dia bodoh."}]},{"pattern":"～わけにはいかない (〜wake ni wa ikanai)","meaning":"Expresses that something cannot be allowed or permitted due to social/moral obligations.","meaningId":"Menyatakan bahwa sesuatu tidak boleh atau diperbolehkan karena kewajiban sosial/moral.","formation":"Verb-casual + わけにはいかない","formationId":"Kata kerja-kasual + わけにはいかない","examples":[{"jp":"こんなところで寝るわけにはいかない。","romaji":"Konna tokoro de neru wake ni wa ikanai.","en":"I can't possibly sleep in a place like this.","id":"Aku tidak mungkin tidur di tempat seperti ini."},{"jp":"試験が明日だから、遊びに行くわけにはいかない。","romaji":"Shiken ga ashita dakara, asobi ni iku wake ni wa ikanai.","en":"I can't afford to go out to have fun, since the exam is tomorrow.","id":"Saya tidak mampu keluar untuk bersenang-senang, karena ujiannya besok."},{"jp":"こんなに高いものを買うわけにはいかない。","romaji":"Konna ni takai mono wo kau wake ni wa ikanai.","en":"I can't allow myself to purchase something so expensive.","id":"Saya tidak bisa membiarkan diri saya membeli sesuatu yang begitu mahal."},{"jp":"体調が悪いから、パーティーに参加するわけにはいかない。","romaji":"Taichou ga warui kara, paatii ni sanka suru wake ni wa ikanai.","en":"Since I'm not feeling well, I can't attend the party.","id":"Karena aku merasa tidak enak badan, aku tidak bisa menghadiri pestanya."}]},{"pattern":"～わりには (〜wari ni wa)","meaning":"Expresses contrast between expectation and reality; 'despite', 'considering', 'even though'.","meaningId":"Mengungkapkan kontras antara harapan dan kenyataan; 'meskipun', 'mempertimbangkan', 'meskipun'.","formation":"Verb-casual + わりには, い-Adjective + わりには, な-Adjective + だわりには, Noun + だわりには","formationId":"Kata Kerja-kasual + わりには, い-Kata Sifat + わりには, な-Kata Sifat + だわりには, Kata Benda + だわりには","examples":[{"jp":"彼はあまり勉強しないわりには、テストの点数が高いです。","romaji":"Kare wa amari benkyou shinai wari ni wa, tesuto no tensuu ga takai desu.","en":"Despite not studying much, he gets high scores on tests.","id":"Meski tidak banyak belajar, ia mendapat nilai tinggi dalam ujian."},{"jp":"この料理は見た目が悪いわりには、味は美味しいです。","romaji":"Kono ryouri wa mitame ga warui wari ni wa, aji wa oishii desu.","en":"Even though this dish doesn't look good, it tastes delicious.","id":"Meski tampilannya kurang enak, namun rasanya enak."},{"jp":"彼女は若いわりには、とても落ち着いていますね。","romaji":"Kanojo wa wakai wari ni wa, totemo ochitsuite imasu ne.","en":"Considering she's young, she's very calm.","id":"Mengingat dia masih muda, dia sangat tenang."},{"jp":"この部屋は狭いわりには、家賃が高いです。","romaji":"Kono heya wa semai wari ni wa, yachin ga takai desu.","en":"Despite being small, this room’s rent is high.","id":"Meski kecil, harga sewa kamar ini mahal."}]},{"pattern":"～んだって (〜n datte)","meaning":"Conveys information heard from someone else; 'I heard', 'They said'.","meaningId":"Menyampaikan informasi yang didengar dari orang lain; 'Saya mendengar', 'Mereka berkata'.","formation":"Verb-casual + んだって, い-Adjective + んだって, な-Adjective + なんだって, Noun + なんだって","formationId":"Kata Kerja-kasual + んだって, い-Kata Sifat + んだって, な-Kata Sifat + なんだって, Kata Benda + なんだって","examples":[{"jp":"彼は東京に行くんだって。","romaji":"Kare wa Toukyou ni iku n datte.","en":"I heard he's going to Tokyo.","id":"Kudengar dia akan ke Tokyo."},{"jp":"この映画、面白いんだって。","romaji":"Kono eiga, omoshiroi n datte.","en":"They said this movie is interesting.","id":"Mereka bilang film ini menarik."},{"jp":"彼女は有名な歌手なんだって。","romaji":"Kanojo wa yuumei na kashu na n datte.","en":"I heard she's a famous singer.","id":"Kudengar dia penyanyi terkenal."},{"jp":"あのレストラン、夜景がきれいなんだって。","romaji":"Ano resutoran, yakei ga kirei na n datte.","en":"They said the night view at that restaurant is beautiful.","id":"Katanya pemandangan malam di restoran itu indah."}]},{"pattern":"～んだもん (〜nda mon)","meaning":"Used to convey a sense of justification; 'because', 'that's why', 'it's just that'.","meaningId":"Digunakan untuk menyampaikan rasa pembenaran; 'karena', 'itu sebabnya', 'hanya saja'.","formation":"Verb-casual + んだもん, い-Adjective + んだもん, な-Adjective + なんだもん, Noun + なんだもん","formationId":"Kata Kerja-kasual + んだもん, い-Kata Sifat + んだもん, な-Kata Sifat + なんだもん, Kata Benda + なんだもん","examples":[{"jp":"遅れたんだもん、ごめん。","romaji":"Okureta nda mon, gomen.","en":"I was late, that's why I'm sorry.","id":"Aku terlambat, makanya aku minta maaf."},{"jp":"おいしいんだもん、もうちょっと食べたい。","romaji":"Oishii nda mon, mou chotto tabetai.","en":"It's delicious, that's why I want to eat more.","id":"Enak, makanya saya ingin makan lebih banyak."},{"jp":"疲れているんだもん、早く寝たい。","romaji":"Tsukarete iru nda mon, hayaku netai.","en":"I'm tired, that's why I want to go to bed early.","id":"Aku lelah, makanya aku ingin tidur lebih awal."},{"jp":"彼は友達なんだもん、手伝わないわけにはいかない。","romaji":"Kare wa tomodachi nan da mon, tetsudawanai wake ni wa ikanai.","en":"He's my friend, that's why I can't not help him.","id":"Dia temanku, itu sebabnya aku tidak bisa tidak membantunya."}]},{"pattern":"～上げる (〜ageru)","meaning":"Indicates to finish doing something completely.","meaningId":"Menandakan untuk menyelesaikan melakukan sesuatu secara tuntas.","formation":"Verb-ますstem + 上げる","formationId":"Kata kerja-ますbatang + 上げる","examples":[{"jp":"レポートを書き上げるまで、寝られません。","romaji":"Repooto o kakiageru made, neraremasen.","en":"I cannot sleep until I finish writing the report.","id":"Saya tidak bisa tidur sampai saya selesai menulis laporan."},{"jp":"彼女は早速部屋の掃除を始め、一時間で掃除をやり上げた。","romaji":"Kanojo wa sassoku heya no souji o hajime, ichijikan de souji o yariageta.","en":"She started cleaning the room right away and finished cleaning it in an hour.","id":"Dia segera mulai membersihkan kamar dan selesai membersihkannya dalam satu jam."},{"jp":"試験前夜、勉強をやり上げてから寝た。","romaji":"Shiken zenya, benkyou o yariagete kara neta.","en":"I went to bed after finishing studying on the night before the exam.","id":"Saya pergi tidur setelah selesai belajar pada malam sebelum ujian."},{"jp":"このプロジェクトをやり上げるためには、みんなの協力が必要です。","romaji":"Kono purojekuto o yariageru tame ni wa, minna no kyouryoku ga hitsuyou desu.","en":"To finish this project, everyone's cooperation is needed.","id":"Untuk menyelesaikan proyek ini, diperlukan kerja sama semua pihak."}]},{"pattern":"～切れない","meaning":"Expresses inability to completely finish or do something.","meaningId":"Mengekspresikan ketidakmampuan untuk sepenuhnya menyelesaikan atau melakukan sesuatu.","formation":"Verb-stem + 切れない","formationId":"Batang kata kerja + 切れない","examples":[{"jp":"この本を一晩で読み切れない。","romaji":"Kono hon wo hitoban de yomikirenai.","en":"I cannot finish reading this book in one night.","id":"Saya tidak bisa menyelesaikan membaca buku ini dalam satu malam."},{"jp":"彼は泣き切れないほど嬉しかった。","romaji":"Kare wa nakikirenai hodo ureshikatta.","en":"He was so happy that he couldn't stop crying.","id":"Dia sangat bahagia hingga dia tidak bisa berhenti menangis."},{"jp":"この部屋を一日で掃除し切れない。","romaji":"Kono heya wo ichinichi de soujishikirenai.","en":"I cannot finish cleaning this room in one day.","id":"Saya tidak bisa menyelesaikan pembersihan ruangan ini dalam satu hari."},{"jp":"彼女は話し切れないほどの悩みがある。","romaji":"Kanojo wa hanashikirenai hodo no nayami ga aru.","en":"She has so many worries that she can't finish talking about them.","id":"Dia mempunyai begitu banyak kekhawatiran sehingga dia tidak dapat menyelesaikan pembicaraannya."}]},{"pattern":"必ずしも～とは限らない","meaning":"Not necessarily; not always.","meaningId":"Belum tentu; tidak selalu.","formation":"必ずしも + Statement + とは限らない","formationId":"必ずしも + Pernyataan + とは限らない","examples":[{"jp":"高いものが必ずしも良いとは限らない。","romaji":"Takai mono ga kanarazushimo yoi to wa kagiranai.","en":"Expensive things are not necessarily better.","id":"Barang mahal belum tentu lebih baik."},{"jp":"有名な人が必ずしも幸せとは限らない。","romaji":"Yuumei na hito ga kanarazushimo shiawase to wa kagiranai.","en":"Famous people are not necessarily happy.","id":"Orang terkenal belum tentu bahagia."},{"jp":"外国語が話せる人が必ずしも英語が得意とは限らない。","romaji":"Gaikokugo ga hanaseru hito ga kanarazushimo eigo ga tokui to wa kagiranai.","en":"People who can speak a foreign language are not always good at English.","id":"Orang yang bisa berbahasa asing tidak selalu pandai berbahasa Inggris."},{"jp":"勉強時間が多い生徒が必ずしも試験で点数が高いとは限らない。","romaji":"Benkyou jikan ga ooi seito ga kanarazushimo shiken de tensuu ga takai to wa kagiranai.","en":"Students who study a lot are not necessarily scoring high on exams.","id":"Siswa yang banyak belajar belum tentu mendapat nilai tinggi dalam ujian."}]},{"pattern":"～最中に","meaning":"In the middle of / while doing something.","meaningId":"Di tengah / saat melakukan sesuatu.","formation":"Verb-て form + いる + 最中に, Noun + の + 最中に","formationId":"Bentuk kata kerja-て + いる + 最中に, Kata Benda + の + 最中に","examples":[{"jp":"昼寝をしている最中に電話が鳴った。","romaji":"Hirune o shiteiru saichuu ni denwa ga natta.","en":"The phone rang while I was taking a nap.","id":"Telepon berdering ketika saya sedang tidur siang."},{"jp":"料理を作っている最中に火事が起こった。","romaji":"Ryouri o tsukutteiru saichuu ni kaji ga okotta.","en":"A fire broke out in the middle of cooking.","id":"Kebakaran terjadi di tengah proses memasak."},{"jp":"会議の最中に急な用事で出なければならなかった。","romaji":"Kaigi no saichuu ni kyuu na youji de denakereba naranakatta.","en":"I had to leave during the meeting because of an urgent matter.","id":"Saya harus pergi saat rapat karena ada urusan yang mendesak."},{"jp":"試験の最中に地震が起こった。","romaji":"Shiken no saichuu ni jishin ga okotta.","en":"An earthquake occurred during the exam.","id":"Gempa bumi terjadi saat ujian."}]},{"pattern":"決して～ない","meaning":"Express 'never', 'by no means', or 'not at all' when negating a statement.","meaningId":"Ekspresikan 'tidak pernah', 'sama sekali tidak', atau 'tidak sama sekali' ketika meniadakan suatu pernyataan.","formation":"決して + Verb (negative form)","formationId":"決して + Kata Kerja (bentuk negatif)","examples":[{"jp":"彼は決して遅刻しない。","romaji":"Kare wa kesshite chikoku shinai.","en":"He never arrives late.","id":"Dia tidak pernah datang terlambat."},{"jp":"この秘密を決して誰にも言わないでください。","romaji":"Kono himitsu o kesshite darenimo iwanai de kudasai.","en":"Please never tell this secret to anyone.","id":"Tolong jangan pernah menceritakan rahasia ini kepada siapa pun."},{"jp":"決して諦めないで、最後までがんばりましょう。","romaji":"Kesshite akiramenai de, saigo made ganbarimashou.","en":"Never give up and keep trying until the end.","id":"Jangan pernah menyerah dan terus berusaha sampai akhir."},{"jp":"彼女は決して嘘をつかない人です。","romaji":"Kanojo wa kesshite uso o tsukanai hito desu.","en":"She is a person who never lies.","id":"Dia adalah orang yang tidak pernah berbohong."}]}]
